import { useEffect, useState, type ReactNode } from 'react';
import * as XLSX from 'xlsx';
import { useManagerShellNavigation } from '../ManagerShell';
import { useTenantQuery } from '../../hooks/useTenantQuery';
import { enterpriseGroupsService, type ManagerAccountingModuleResponse } from '../../services/enterprise-groups.service';
import { Card, CardContent, CardHeader, CardTitle } from '../ui/card';
import { Button } from '../ui/button';
import { Badge } from '../ui/badge';
import { Input } from '../ui/input';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '../ui/table';
import { BarChart3, BookOpen, Building2, CalendarDays, ChevronLeft, ChevronRight, ClipboardCheck, Download, FileBarChart, FileSpreadsheet, Landmark, LayoutDashboard, LayoutGrid, List, Loader2, RefreshCw, Search, Scale, TrendingDown, TrendingUp, Wallet } from 'lucide-react';
import { cn } from '../ui/utils';
import { useCardsOnlyBelowTableBreakpoint } from '../ui/ViewLayoutSelect';
import { MANAGER_ACCOUNTING_VIEWS, type ManagerAccountingView } from './manager-accounting.types';

type BranchOption = { id: string; name: string; businessUnitId?: string | null };
type LayoutMode = 'table' | 'cards';
type Column = { label: string; numeric?: boolean; render: (row: any) => ReactNode };

const numberFormat = new Intl.NumberFormat('es-NI', { maximumFractionDigits: 2 });
const formatNumber = (value: unknown) => numberFormat.format(Number(value || 0));
const formatMoney = (value: unknown, currency = 'NIO') => `${currency} ${formatNumber(value)}`;
const formatDate = (value: unknown) => { if (!value) return '—'; const date = new Date(String(value)); return Number.isNaN(date.getTime()) ? '—' : date.toLocaleDateString('es-NI'); };
const statusLabel = (value: unknown) => String(value || '—').replaceAll('_', ' ');
const labels = Object.fromEntries(MANAGER_ACCOUNTING_VIEWS.map((item) => [item.id, item.label])) as Record<ManagerAccountingView, string>;
const icons: Record<ManagerAccountingView, typeof BookOpen> = { overview: LayoutDashboard, chart: BookOpen, journal: FileSpreadsheet, ledger: BookOpen, trialBalance: Scale, profitLoss: TrendingUp, balanceSheet: BarChart3, cashFlow: Wallet, exchange: TrendingUp, equity: FileSpreadsheet, assets: Building2, bankBook: Landmark, reconciliation: ClipboardCheck, periods: CalendarDays, fiscal: FileBarChart, invoiceAudit: ClipboardCheck, budgets: BarChart3, expenseCategories: FileSpreadsheet, hrPaymentRequests: ClipboardCheck };

export function ManagerAccountingModule({ view, onViewChange, groupId, businessUnitId, branchId, branches }: { view: ManagerAccountingView; onViewChange: (view: ManagerAccountingView) => void; groupId: string; businessUnitId?: string; branchId?: string; branches: BranchOption[] }) {
  const { sidebarCollapsed } = useManagerShellNavigation();
  const [search, setSearch] = useState(''); const [debouncedSearch, setDebouncedSearch] = useState(''); const [status, setStatus] = useState(''); const [dateFrom, setDateFrom] = useState(''); const [dateTo, setDateTo] = useState(''); const [page, setPage] = useState(1); const [pageSize, setPageSize] = useState(25); const [layoutMode, setLayoutMode] = useState<LayoutMode>('table'); const isCompactTableViewport = useCardsOnlyBelowTableBreakpoint(); const effectiveLayoutMode: LayoutMode = isCompactTableViewport ? 'cards' : layoutMode; const [exporting, setExporting] = useState(false);
  const query = useTenantQuery<ManagerAccountingModuleResponse>(['manager-accounting-module', groupId, view, businessUnitId || 'all', branchId || 'all', debouncedSearch, status, dateFrom, dateTo, page, pageSize], (signal) => enterpriseGroupsService.getAccountingModule(groupId, { view, businessUnitId, branchId, search: debouncedSearch || undefined, status: status || undefined, dateFrom: dateFrom || undefined, dateTo: dateTo || undefined, page, pageSize }, signal), { enabled: Boolean(groupId) });
  const response = query.data; const rows = response?.data || []; const metrics = response?.metrics || {}; const showBranch = !branchId && branches.length > 1;
  useEffect(() => { const timer = window.setTimeout(() => setDebouncedSearch(search), 300); return () => window.clearTimeout(timer); }, [search]);
  const changeView = (next: ManagerAccountingView) => { setPage(1); setSearch(''); setStatus(''); setDateFrom(''); setDateTo(''); onViewChange(next); };
  const exportReport = async () => { setExporting(true); try { const report = await enterpriseGroupsService.getAccountingModule(groupId, { view, businessUnitId, branchId, search: search || undefined, status: status || undefined, dateFrom: dateFrom || undefined, dateTo: dateTo || undefined, page: 1, pageSize: 5000, report: true }); const workbook = XLSX.utils.book_new(); const exportRows = (report.data || []).map((row: any) => ({ Vista: labels[view], Identificador: row.number || row.code || row.name || row.id, Fecha: formatDate(row.date || row.createdAt), Cuenta: row.accountName || row.name || '', Debe: row.debit ?? '', Haber: row.credit ?? '', Saldo: row.balance ?? '', Estado: statusLabel(row.status), Sucursal: row.branchName || '', Rubro: row.businessUnitName || '' })); XLSX.utils.book_append_sheet(workbook, XLSX.utils.json_to_sheet(exportRows.length ? exportRows : [{ Mensaje: 'Sin registros para el alcance seleccionado' }]), 'Contabilidad'); XLSX.writeFile(workbook, `manager-contabilidad-${view}.xlsx`); } finally { setExporting(false); } };
  const Icon = icons[view] || BookOpen;
  return <div className="accounting-module min-w-0 space-y-5 overflow-x-hidden p-4 sm:p-6 md:p-8"><div className="flex min-w-0 flex-col gap-4 md:flex-row md:items-start md:justify-between"><div className="flex min-w-0 items-start gap-3"><div className="flex size-12 shrink-0 items-center justify-center rounded-2xl bg-primary/10 text-primary"><Icon className="size-6" /></div><div className="min-w-0"><h1 className="truncate text-3xl font-black uppercase italic tracking-tighter sm:text-4xl">Contabilidad <span className="text-primary">consolidada</span></h1><p className="mt-1 text-sm text-muted-foreground">Consulta contable consolidada por rubro y sucursal.</p><Badge variant="outline" className="mt-3 border-primary/20 bg-primary/10 text-[10px] font-black uppercase tracking-widest text-primary">{branches.length} sucursal(es) en el alcance</Badge></div></div><div className="flex shrink-0 flex-wrap gap-2"><Button variant="outline" className="rounded-xl" onClick={() => void query.refetch()} disabled={query.isFetching}><RefreshCw className={cn('mr-2 size-4', query.isFetching && 'animate-spin')} />Actualizar</Button><Button variant="outline" className="rounded-xl" onClick={() => void exportReport()} disabled={exporting}>{exporting ? <Loader2 className="mr-2 size-4 animate-spin" /> : <Download className="mr-2 size-4" />}Exportar Excel</Button></div></div>{sidebarCollapsed && <div className="manager-module-subnav flex min-w-0 gap-2 overflow-x-auto rounded-2xl border border-border/60 bg-muted/30 p-1.5">{MANAGER_ACCOUNTING_VIEWS.map((item) => <button key={item.id} type="button" onClick={() => changeView(item.id)} className={cn('flex-none rounded-xl px-3 py-2 text-[11px] font-black uppercase tracking-wide text-muted-foreground transition-colors hover:bg-card hover:text-foreground', view === item.id && 'bg-primary text-primary-foreground shadow-sm')}><span className="sm:hidden">{item.label.slice(0, 3)}</span><span className="hidden sm:inline">{item.label}</span></button>)}</div>}{view === 'overview' ? <AccountingOverview metrics={metrics} /> : <><AccountingFilters search={search} setSearch={(value) => { setSearch(value); setPage(1); }} status={status} setStatus={(value) => { setStatus(value); setPage(1); }} dateFrom={dateFrom} setDateFrom={(value) => { setDateFrom(value); setPage(1); }} dateTo={dateTo} setDateTo={(value) => { setDateTo(value); setPage(1); }} layoutMode={effectiveLayoutMode} setLayoutMode={setLayoutMode} /><AccountingKpis view={view} metrics={metrics} />{query.isLoading ? <LoadingState /> : query.error ? <EmptyState title="No se pudo cargar la vista" description="Verifica el permiso Manager de Contabilidad y vuelve a actualizar." /> : effectiveLayoutMode === 'cards' ? <AccountingCards view={view} rows={rows} showBranch={showBranch} /> : <AccountingTable view={view} rows={rows} showBranch={showBranch} />}<Pagination page={response?.meta.page || page} totalPages={response?.meta.totalPages || 1} total={response?.meta.total || 0} totalRows={response?.meta.total || 0} pageSize={pageSize} onPageChange={setPage} onPageSizeChange={(value) => { setPageSize(value); setPage(1); }} /></>}</div>;
}

function AccountingOverview({ metrics }: { metrics: Record<string, any> }) { const cards = [['Cuentas', metrics.accounts, BookOpen], ['Asientos', metrics.journals, FileSpreadsheet], ['Movimientos', metrics.transactions, BarChart3], ['Debe', formatMoney(metrics.debit), TrendingUp], ['Haber', formatMoney(metrics.credit), TrendingDown], ['Diferencia', formatMoney(metrics.difference), Scale], ['Períodos', metrics.periods, CalendarDays], ['Activos fijos', metrics.assets, Building2]] as const; return <div className="space-y-5"><div className="grid grid-cols-1 gap-4 sm:grid-cols-2 xl:grid-cols-4">{cards.map(([label, value, CardIcon]) => <Card key={label} className="rounded-2xl border-border/60 shadow-sm"><CardContent className="flex items-center gap-4 p-5"><div className="flex size-11 shrink-0 items-center justify-center rounded-xl bg-primary/10 text-primary"><CardIcon className="size-5" /></div><div className="min-w-0"><p className="text-[10px] font-black uppercase tracking-widest text-muted-foreground">{label}</p><p className="mt-1 truncate text-2xl font-black tracking-tight">{typeof value === 'number' ? formatNumber(value) : value || '0'}</p></div></CardContent></Card>)}</div><Card className="rounded-3xl border-primary/20 bg-primary/5"><CardHeader><CardTitle className="text-lg font-black uppercase italic tracking-tight">Lectura contable</CardTitle></CardHeader><CardContent className="grid grid-cols-1 gap-4 text-sm md:grid-cols-3"><div><p className="text-muted-foreground">Estado de cuadre</p><p className="mt-1 font-black">{Math.abs(Number(metrics.difference || 0)) < 0.01 ? 'Debe y Haber conciliados' : 'Requiere revisión'}</p></div><div><p className="text-muted-foreground">Cuenta con mayor saldo</p><p className="mt-1 font-black">{metrics.topAccountName || 'Sin datos'}</p></div><div><p className="text-muted-foreground">Datos informativos</p><p className="mt-1 font-semibold text-muted-foreground">Las operaciones y ajustes se realizan dentro de cada sucursal.</p></div></CardContent></Card></div>; }
function AccountingFilters({ search, setSearch, status, setStatus, dateFrom, setDateFrom, dateTo, setDateTo, layoutMode, setLayoutMode }: { search: string; setSearch: (value: string) => void; status: string; setStatus: (value: string) => void; dateFrom: string; setDateFrom: (value: string) => void; dateTo: string; setDateTo: (value: string) => void; layoutMode: LayoutMode; setLayoutMode: (value: LayoutMode) => void }) { return <Card className="rounded-3xl border-border/60 shadow-sm"><CardContent className="grid min-w-0 grid-cols-1 gap-3 p-4 md:grid-cols-2 xl:grid-cols-[minmax(220px,1.4fr)_minmax(150px,0.7fr)_minmax(150px,0.7fr)_auto] xl:items-end"><label className="min-w-0 space-y-1.5 text-xs font-bold text-muted-foreground"><span>Buscar</span><div className="relative"><Search className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2" /><Input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Código, cuenta, número..." className="pl-9" /></div></label><label className="space-y-1.5 text-xs font-bold text-muted-foreground"><span>Estado</span><select value={status} onChange={(event) => setStatus(event.target.value)} className="erp-filter-select h-10 rounded-xl border border-border bg-background px-3 text-sm font-normal"><option value="">Todos</option><option value="ACTIVE">Activo</option><option value="OPEN">Abierto</option><option value="CLOSED">Cerrado</option><option value="DRAFT">Borrador</option><option value="FINAL">Final</option></select></label><label className="space-y-1.5 text-xs font-bold text-muted-foreground"><span>Fecha desde</span><Input type="date" value={dateFrom} onChange={(event) => setDateFrom(event.target.value)} /></label><label className="space-y-1.5 text-xs font-bold text-muted-foreground"><span>Fecha hasta</span><Input type="date" value={dateTo} onChange={(event) => setDateTo(event.target.value)} /></label><div className="flex items-center justify-end gap-1 rounded-xl border border-border/60 bg-muted/20 p-1"><Button type="button" variant={layoutMode === 'table' ? 'secondary' : 'ghost'} size="icon" className="size-9 rounded-lg" onClick={() => setLayoutMode('table')} aria-label="Vista tabla"><List className="size-4" /></Button><Button type="button" variant={layoutMode === 'cards' ? 'secondary' : 'ghost'} size="icon" className="size-9 rounded-lg" onClick={() => setLayoutMode('cards')} aria-label="Vista tarjetas"><LayoutGrid className="size-4" /></Button></div></CardContent></Card>; }
function AccountingKpis({ view, metrics }: { view: ManagerAccountingView; metrics: Record<string, any> }) { const cards = [['Registros', metrics.total], ['Debe', formatMoney(metrics.debit)], ['Haber', formatMoney(metrics.credit)], [view === 'balanceSheet' ? 'Activo total' : 'Saldo', formatMoney(metrics.balance ?? metrics.net)]]; return <div className="grid grid-cols-1 gap-3 sm:grid-cols-2 xl:grid-cols-4">{cards.map(([label, value]) => <div key={String(label)} className="rounded-2xl border border-border/60 bg-card p-4 shadow-sm"><p className="text-[10px] font-black uppercase tracking-widest text-muted-foreground">{label}</p><p className="mt-2 truncate text-xl font-black">{typeof value === 'number' ? formatNumber(value) : value || '0'}</p></div>)}</div>; }
function AccountingTable({ view, rows, showBranch }: { view: ManagerAccountingView; rows: any[]; showBranch: boolean }) { const columns = tableColumns(view, showBranch); return <Card className="overflow-hidden rounded-3xl border-border/60 shadow-sm"><CardHeader className="border-b border-border/60"><CardTitle className="text-lg font-black uppercase italic tracking-tight">{labels[view]}</CardTitle><p className="text-sm text-muted-foreground">Ordenado de lo más reciente a lo más antiguo. Los datos son de solo lectura.</p></CardHeader><CardContent className="p-0">{rows.length ? <div className="sales-responsive-table overflow-x-auto"><Table className="min-w-[980px]"><TableHeader><TableRow>{columns.map((column) => <TableHead key={column.label}>{column.label}</TableHead>)}</TableRow></TableHeader><TableBody>{rows.map((row) => <TableRow key={row.id}>{columns.map((column) => <TableCell key={`${row.id}-${column.label}`} className={cn('max-w-64', column.numeric && 'text-right font-semibold')}>{column.render(row)}</TableCell>)}</TableRow>)}</TableBody></Table></div> : <EmptyState title="Sin registros" description="No hay información para el rubro, sucursal y filtros seleccionados." />}</CardContent></Card>; }
function AccountingCards({ view, rows, showBranch }: { view: ManagerAccountingView; rows: any[]; showBranch: boolean }) { if (!rows.length) return <EmptyState title="Sin registros" description="No hay información para el rubro, sucursal y filtros seleccionados." />; return <div className="grid grid-cols-1 gap-3 md:grid-cols-2 xl:grid-cols-3">{rows.map((row) => <Card key={row.id} className="rounded-2xl border-border/60 shadow-sm"><CardContent className="space-y-3 p-5"><div className="flex items-start justify-between gap-3"><div className="min-w-0"><p className="truncate text-base font-black">{row.number || row.code || row.name || row.id?.slice(0, 8)}</p><p className="text-xs text-muted-foreground">{row.description || row.accountName || labels[view]}</p></div>{row.status && <Badge variant="outline" className="shrink-0 capitalize">{statusLabel(row.status)}</Badge>}</div><div className="grid grid-cols-2 gap-2 text-sm"><div><p className="text-xs text-muted-foreground">Fecha</p><p className="font-semibold">{formatDate(row.date || row.createdAt)}</p></div><div><p className="text-xs text-muted-foreground">Saldo</p><p className="font-black">{formatMoney(row.balance ?? row.debit ?? row.credit, row.currency)}</p></div></div>{showBranch && <p className="border-t border-border/60 pt-2 text-xs font-semibold text-primary">{row.branchName || 'Sucursal'}</p>}</CardContent></Card>)}</div>; }
function tableColumns(view: ManagerAccountingView, showBranch: boolean): Column[] { const branch = { label: 'Sucursal', render: (row: any) => <span className="font-semibold text-primary">{row.branchName || 'Sucursal'}</span> }; const accountColumns: Column[] = [{ label: 'Código', render: (row) => <span className="font-mono font-semibold text-primary">{row.code || '—'}</span> }, { label: 'Cuenta', render: (row) => row.name || row.accountName || '—' }, { label: 'Tipo', render: (row) => statusLabel(row.type) }, { label: 'Saldo', numeric: true, render: (row) => formatMoney(row.balance, row.currency) }]; const journalColumns: Column[] = [{ label: 'Número', render: (row) => <span className="font-semibold">{row.number}</span> }, { label: 'Fecha', render: (row) => formatDate(row.date) }, { label: 'Descripción', render: (row) => row.description || '—' }, { label: 'Estado', render: (row) => statusLabel(row.status) }]; const movementColumns: Column[] = [{ label: 'Fecha', render: (row) => formatDate(row.date) }, { label: 'Cuenta', render: (row) => row.accountName || row.name || '—' }, { label: 'Descripción', render: (row) => row.description || '—' }, { label: 'Debe', numeric: true, render: (row) => formatMoney(row.debit) }, { label: 'Haber', numeric: true, render: (row) => formatMoney(row.credit) }, { label: 'Saldo', numeric: true, render: (row) => formatMoney(row.balance) }]; const simpleColumns: Column[] = [{ label: 'Registro', render: (row) => <span className="font-semibold">{row.number || row.code || row.name || '—'}</span> }, { label: 'Fecha', render: (row) => formatDate(row.date || row.createdAt || row.startDate) }, { label: 'Descripción', render: (row) => row.description || row.name || row.type || '—' }, { label: 'Estado', render: (row) => <Badge variant="outline" className="capitalize">{statusLabel(row.status)}</Badge> }, { label: 'Monto', numeric: true, render: (row) => formatMoney(row.amount ?? row.total ?? row.balance) }]; const columns = view === 'chart' ? accountColumns : view === 'journal' ? journalColumns : ['ledger', 'trialBalance', 'profitLoss', 'balanceSheet', 'cashFlow', 'bankBook'].includes(view) ? movementColumns : simpleColumns; return showBranch ? [...columns, branch] : columns; }
function Pagination({ page, totalPages, total, totalRows, pageSize, onPageChange, onPageSizeChange }: { page: number; totalPages: number; total: number; totalRows: number; pageSize: number; onPageChange: (page: number) => void; onPageSizeChange: (size: number) => void }) { return <div className="flex flex-col gap-3 text-sm text-muted-foreground sm:flex-row sm:items-center sm:justify-between"><span>{formatNumber(totalRows || total)} registro(s)</span><div className="flex items-center gap-2"><select value={pageSize} onChange={(event) => onPageSizeChange(Number(event.target.value))} className="h-9 rounded-lg border border-border bg-background px-2 text-xs"><option value={25}>25 / página</option><option value={50}>50 / página</option><option value={100}>100 / página</option></select><Button variant="outline" size="icon" className="size-9 rounded-lg" onClick={() => onPageChange(Math.max(1, page - 1))} disabled={page <= 1}><ChevronLeft className="size-4" /></Button><span className="min-w-20 text-center text-xs font-semibold">Página {page} de {totalPages}</span><Button variant="outline" size="icon" className="size-9 rounded-lg" onClick={() => onPageChange(Math.min(totalPages, page + 1))} disabled={page >= totalPages}><ChevronRight className="size-4" /></Button></div></div>; }
function LoadingState() { return <div className="flex min-h-48 items-center justify-center text-sm text-muted-foreground"><RefreshCw className="mr-2 size-5 animate-spin" />Cargando contabilidad consolidada...</div>; }
function EmptyState({ title, description }: { title: string; description: string }) { return <div className="rounded-3xl border border-dashed border-border p-10 text-center"><p className="font-black">{title}</p><p className="mt-1 text-sm text-muted-foreground">{description}</p></div>; }
