import { useEffect, useMemo, useState, type ReactNode } from 'react';
import { Banknote, Building2, CalendarDays, ChevronLeft, ChevronRight, ClipboardList, CreditCard, Download, LayoutGrid, List, Loader2, PackageCheck, Receipt, RefreshCw, Search, Truck, Users, WalletCards } from 'lucide-react';
import { useManagerShellNavigation } from '../ManagerShell';
import { useTenantQuery } from '../../hooks/useTenantQuery';
import { enterpriseGroupsService, type ManagerPurchasesDocumentDetailResponse, type ManagerPurchasesModuleResponse } from '../../services/enterprise-groups.service';
import { useAuth } from '../../contexts/AuthContext';
import { useTheme } from '../../contexts/ThemeContext';
import { Card, CardContent, CardHeader, CardTitle } from '../ui/card';
import { Button } from '../ui/button';
import { Badge } from '../ui/badge';
import { Input } from '../ui/input';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '../ui/table';
import { PdfDownloadButton } from '../ui/PdfDownloadButton';
import type { PdfDownloadFormat } from '../../utils/pdfDownloadFormats';
import { ColumnFilterMenu, type ColumnSort, type ColumnSortType } from '../ui/ColumnFilterMenu';
import { useCardsOnlyBelowTableBreakpoint } from '../ui/ViewLayoutSelect';
import { formatCurrencyAmount, formatCurrencyDescriptor } from '../../utils/currency';
import { exportManagerSalesExcel, exportManagerSalesPdf } from '../../utils/managerSalesExport';
import { SalesDocumentDetailSheet, type SalesDocumentPanelData } from '../ventas/SalesDocumentDetailSheet';
import { MANAGER_PURCHASES_VIEWS, type ManagerPurchasesView } from './manager-purchases.types';
import { cn } from '../ui/utils';
import { toast } from 'sonner';

type BranchOption = { id: string; name: string; businessUnitId?: string | null };
type LayoutMode = 'table' | 'cards';
type PurchaseColumn = { key: string; label: string; numeric?: boolean; sortType?: ColumnSortType; getValue: (row: any) => unknown; render: (row: any) => ReactNode };

const numberFormat = new Intl.NumberFormat('es-NI', { maximumFractionDigits: 2 });
const formatNumber = (value: unknown) => numberFormat.format(Number(value || 0));
const formatMoney = (value: unknown, currency = 'NIO', includeCode = false) => formatCurrencyAmount(value, currency, includeCode);
const formatDate = (value: unknown, includeTime = false) => {
  if (!value) return '—';
  const date = new Date(String(value));
  if (Number.isNaN(date.getTime())) return '—';
  return date.toLocaleString('es-NI', includeTime ? { dateStyle: 'short', timeStyle: 'short' } : { dateStyle: 'short' });
};
const viewLabels: Record<ManagerPurchasesView, string> = Object.fromEntries(MANAGER_PURCHASES_VIEWS.map((item) => [item.id, item.label])) as Record<ManagerPurchasesView, string>;

const statusOptions: Partial<Record<ManagerPurchasesView, Array<{ value: string; label: string }>>> = {
  orders: [{ value: 'DRAFT', label: 'Borrador' }, { value: 'PENDING', label: 'Pendiente' }, { value: 'APPROVED', label: 'Aprobada' }, { value: 'CANCELLED', label: 'Cancelada' }],
  receipts: [{ value: 'PENDING', label: 'Pendiente' }, { value: 'RECEIVED', label: 'Recibida' }, { value: 'PARTIAL', label: 'Parcial' }, { value: 'REJECTED', label: 'Rechazada' }, { value: 'WITH_INCIDENTS', label: 'Con incidencias' }],
  invoices: [{ value: 'PENDING', label: 'Pendiente' }, { value: 'PARTIAL', label: 'Parcial' }, { value: 'PAID', label: 'Pagada' }, { value: 'OVERDUE', label: 'Vencida' }, { value: 'CANCELLED', label: 'Cancelada' }],
  recurring: [{ value: 'ACTIVE', label: 'Activa' }, { value: 'PAUSED', label: 'Pausada' }, { value: 'EXPIRED', label: 'Vencida' }, { value: 'CANCELLED', label: 'Cancelada' }],
  payments: [{ value: 'CASH', label: 'Efectivo' }, { value: 'TRANSFER', label: 'Transferencia' }, { value: 'CHECK', label: 'Cheque' }, { value: 'CARD', label: 'Tarjeta' }, { value: 'OTHER', label: 'Otro' }],
  credits: [{ value: 'DRAFT', label: 'Borrador' }, { value: 'ISSUED', label: 'Emitido' }, { value: 'APPLIED', label: 'Aplicado' }, { value: 'PAID', label: 'Pagado' }, { value: 'VOIDED', label: 'Anulado' }],
  expenses: [{ value: 'DRAFT', label: 'Borrador' }, { value: 'PENDING', label: 'Pendiente' }, { value: 'APPROVED', label: 'Aprobado' }, { value: 'PAID', label: 'Pagado' }, { value: 'REJECTED', label: 'Rechazado' }],
  recurringexpenses: [{ value: 'ACTIVE', label: 'Activa' }, { value: 'PAUSED', label: 'Pausada' }, { value: 'EXPIRED', label: 'Vencida' }, { value: 'CANCELLED', label: 'Cancelada' }],
  requests: [{ value: 'PENDING_APPROVAL', label: 'Pendiente de aprobación' }, { value: 'APPROVED', label: 'Aprobada' }, { value: 'CANCELLED', label: 'Cancelada' }],
  management: [{ value: 'DRAFT', label: 'Borrador' }, { value: 'PENDING_APPROVAL', label: 'Pendiente de aprobación' }, { value: 'APPROVED', label: 'Aprobada' }, { value: 'REJECTED', label: 'Rechazada' }, { value: 'CONVERTED_TO_ORDER', label: 'Convertida a orden' }],
};

const statusLabel = (value: unknown) => {
  const labels: Record<string, string> = {
    DRAFT: 'Borrador', SENT: 'Enviada', APPROVED: 'Aprobada', CANCELLED: 'Cancelada', PENDING: 'Pendiente',
    PENDING_REVIEW: 'Pendiente de revisión', CONFIRMED: 'Confirmada', IN_PROGRESS: 'En proceso', SHIPPED: 'Enviada', DELIVERED: 'Entregada',
    RECEIVED: 'Recibida', PARTIAL: 'Parcial', REJECTED: 'Rechazada', WITH_INCIDENTS: 'Con incidencias', PAID: 'Pagada', CREDIT: 'A crédito', OVERDUE: 'Vencida', REFUNDED: 'Reembolsada',
    ACTIVE: 'Activa', INACTIVE: 'Inactiva', ARCHIVED: 'Archivada', PAUSED: 'Pausada', EXPIRED: 'Vencida',
    CASH: 'Efectivo', TRANSFER: 'Transferencia', CHECK: 'Cheque', CARD: 'Tarjeta', OTHER: 'Otro', BANK: 'Banco', CREDIT_CARD: 'Tarjeta de crédito', DEBIT_CARD: 'Tarjeta de débito',
    ISSUED: 'Emitida', APPLIED: 'Aplicada', VOIDED: 'Anulada', POSTED: 'Registrada',
    PENDING_APPROVAL: 'Pendiente de aprobación', SUBMITTED: 'Enviada', IN_REVIEW: 'En revisión', IN_QUOTATION: 'En cotización', RETURNED_FOR_CORRECTION: 'Devuelta para corrección', CONVERTED_TO_ORDER: 'Convertida a orden', CLOSED: 'Cerrada',
    SUCCESS: 'Exitosa', FAILED: 'Fallida', SKIPPED: 'Omitida',
    COMPANY: 'Empresa', INDIVIDUAL: 'Particular', INVENTORY: 'Inventario', ASSET: 'Activo fijo', SERVICE: 'Servicio', ADMIN: 'Administrativo',
    NORMAL: 'Normal', URGENT: 'Urgente', CRITICAL: 'Crítica',
    DAILY: 'Diaria', WEEKLY: 'Semanal', BIWEEKLY: 'Quincenal', MONTHLY: 'Mensual', QUARTERLY: 'Trimestral', SEMIANNUAL: 'Semestral', YEARLY: 'Anual',
  };
  const normalized = String(value || '').toUpperCase();
  return labels[normalized] || String(value || '—').replaceAll('_', ' ');
};
const statusBadgeClass = (value: unknown) => {
  const normalized = String(value || '').toUpperCase();
  if (['APPROVED', 'PAID', 'ACTIVE', 'RECEIVED', 'APPLIED'].includes(normalized)) return 'border-emerald-500/25 bg-emerald-500/10 text-emerald-700 dark:text-emerald-300';
  if (['PENDING', 'PARTIAL', 'PENDING_APPROVAL', 'ISSUED', 'TRANSFER'].includes(normalized)) return 'border-sky-500/25 bg-sky-500/10 text-sky-700 dark:text-sky-300';
  if (['REJECTED', 'CANCELLED', 'VOIDED', 'OVERDUE', 'EXPIRED'].includes(normalized)) return 'border-rose-500/25 bg-rose-500/10 text-rose-700 dark:text-rose-300';
  return 'border-amber-500/25 bg-amber-500/10 text-amber-700 dark:text-amber-300';
};
const statusBadge = (value: unknown) => <Badge variant="outline" className={cn('font-black', statusBadgeClass(value))}>{statusLabel(value)}</Badge>;
const branchAttachedColumnKeys = new Set(['code', 'number', 'productId']);

function PurchaseBranchLabel({ branchName }: { branchName?: unknown }) {
  return <span className="flex items-start gap-1.5 text-xs font-semibold text-primary"><Building2 className="mt-0.5 size-3.5 shrink-0" /><span className="break-words">{String(branchName || 'Sucursal no identificada')}</span></span>;
}

export function ManagerPurchasesModule({ view, onViewChange, groupId, businessUnitId, branchId, branches, reportCurrency, onEnterBranch, canEnterBranch = false }: { view: ManagerPurchasesView; onViewChange: (view: ManagerPurchasesView) => void; groupId: string; businessUnitId?: string; branchId?: string; branches: BranchOption[]; reportCurrency: string; onEnterBranch?: (groupId: string, branchId: string) => Promise<void>; canEnterBranch?: boolean }) {
  const { sidebarCollapsed } = useManagerShellNavigation();
  const { user } = useAuth();
  const { themeConfig } = useTheme();
  const [search, setSearch] = useState('');
  const [debouncedSearch, setDebouncedSearch] = useState('');
  const [status, setStatus] = useState('');
  const [supplierType, setSupplierType] = useState('');
  const [dateFrom, setDateFrom] = useState('');
  const [dateTo, setDateTo] = useState('');
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(25);
  const [layoutMode, setLayoutMode] = useState<LayoutMode>('table');
  const [columnSorts, setColumnSorts] = useState<Record<string, ColumnSort>>({});
  const [selected, setSelected] = useState<{ entity: ManagerPurchasesView; row: any } | null>(null);
  const [detail, setDetail] = useState<ManagerPurchasesDocumentDetailResponse | null>(null);
  const [exporting, setExporting] = useState(false);
  const isCompactTableViewport = useCardsOnlyBelowTableBreakpoint();
  const effectiveLayoutMode: LayoutMode = isCompactTableViewport ? 'cards' : layoutMode;
  const query = useTenantQuery<ManagerPurchasesModuleResponse>(
    ['manager-purchases', groupId, view, businessUnitId || 'all', branchId || 'all', debouncedSearch, status, supplierType, dateFrom, dateTo, reportCurrency || 'group-default', page, pageSize],
    (signal) => enterpriseGroupsService.getPurchasesModule(groupId, { view, businessUnitId, branchId, search: debouncedSearch || undefined, status: view === 'payments' ? undefined : status || undefined, method: view === 'payments' ? status || undefined : undefined, supplierType: supplierType || undefined, dateFrom: dateFrom || undefined, dateTo: dateTo || undefined, reportCurrency: reportCurrency || undefined, page, pageSize }, signal),
    { enabled: Boolean(groupId) },
  );
  const response = query.data;
  const rows = response?.data || [];
  const metrics = response?.metrics || {};
  const activeReportCurrency = reportCurrency || metrics.consolidationCurrency || 'NIO';
  const columns = useMemo(() => tableColumns(view, true, activeReportCurrency)
    .filter((column) => column.key !== 'branchName')
    .map((column) => {
      if (!branchAttachedColumnKeys.has(column.key)) return column;
      const render = column.render;
      return { ...column, render: (row: any) => <div className="min-w-40 space-y-1">{render(row)}<PurchaseBranchLabel branchName={row.branchName} /></div> };
    }), [view, activeReportCurrency]);
  const displayRows = useMemo(() => sortRows(rows, columns, columnSorts, view), [rows, columns, columnSorts, view]);
  const activeStatusOptions = statusOptions[view] || [];

  useEffect(() => { const timer = window.setTimeout(() => setDebouncedSearch(search), 300); return () => window.clearTimeout(timer); }, [search]);
  const changeView = (next: ManagerPurchasesView) => { setPage(1); setSearch(''); setStatus(''); setSupplierType(''); setDateFrom(''); setDateTo(''); setSelected(null); setDetail(null); onViewChange(next); };
  const changeColumnSort = (sortKey: string, nextSort: ColumnSort) => setColumnSorts((current) => { const next = Object.fromEntries(Object.entries(current).filter(([key]) => !key.startsWith(`${view}:`))) as Record<string, ColumnSort>; if (nextSort) next[`${view}:${sortKey}`] = nextSort; return next; });
  const filters = { view, businessUnitId, branchId, search: search || undefined, status: view === 'payments' ? undefined : status || undefined, method: view === 'payments' ? status || undefined : undefined, supplierType: supplierType || undefined, dateFrom: dateFrom || undefined, dateTo: dateTo || undefined, reportCurrency: activeReportCurrency, page: 1, pageSize: 5000, report: true };
  const filterSummary = [search && `búsqueda: ${search}`, status && `${view === 'payments' ? 'método' : 'estado'}: ${statusLabel(status)}`, supplierType && `tipo: ${statusLabel(supplierType)}`, dateFrom && `desde: ${dateFrom}`, dateTo && `hasta: ${dateTo}`, `moneda: ${formatCurrencyDescriptor(activeReportCurrency)}`].filter(Boolean).join(' · ');
  const exportReport = async (format: 'xlsx' | PdfDownloadFormat) => {
    setExporting(true);
    try {
      const report = await enterpriseGroupsService.getPurchasesModule(groupId, filters);
      const exportRows = (report.data || []).map((row: any) => exportRow(view, row, activeReportCurrency));
      const options = { rows: exportRows, tenantName: themeConfig?.tenantName || user?.tenantName || 'Empresa', tenantLogo: themeConfig?.logo, primaryColor: themeConfig?.colors?.primary, title: `Compras · ${viewLabels[view]}`, fileBase: `manager-compras-${view}`, reportCurrency: activeReportCurrency, filterSummary, metrics: report.metrics };
      if (format === 'xlsx') await exportManagerSalesExcel(options); else await exportManagerSalesPdf({ ...options, pdfFormat: format });
      toast.success(format === 'xlsx' ? 'Excel generado con los filtros aplicados' : 'PDF generado con el tamaño seleccionado');
    } catch (error) { toast.error(error instanceof Error ? error.message : 'No se pudo generar el reporte'); } finally { setExporting(false); }
  };
  const openDetail = (row: any) => { if (!row?.id || view === 'overview') return; setSelected({ entity: view, row }); setDetail(null); void enterpriseGroupsService.getPurchasesDocumentDetail(groupId, view, row.id, activeReportCurrency).then(setDetail).catch(() => toast.error('No se pudo cargar el detalle del registro')); };
  const document = detail?.document || selected?.row || null;
  const panel = document ? buildPurchasePanel(document, activeReportCurrency, detail?.history || []) : null;
  const branchTargetId = String(document?.branchId || document?.clientTenantId || selected?.row?.branchId || '');
  const supplierPhone = String(document?.supplierPhone || selected?.row?.supplierPhone || selected?.row?.supplier?.phone || selected?.row?.phone || '').trim();
  const goToBranch = onEnterBranch && canEnterBranch && branchTargetId ? () => { setSelected(null); void onEnterBranch(groupId, branchTargetId); } : undefined;
  const sendWhatsApp = supplierPhone ? () => { const phone = supplierPhone.replace(/\D/g, ''); const normalized = phone.length === 8 ? `505${phone}` : phone.startsWith('505') ? phone : `505${phone}`; window.open(`https://wa.me/${normalized}?text=${encodeURIComponent(`Hola ${document?.supplierName || 'proveedor'}, te compartimos información de ${document?.title?.toLowerCase() || 'la compra'} ${document?.number || ''}.`)}`, '_blank', 'noopener,noreferrer'); } : undefined;
  const downloadDetail = (format: PdfDownloadFormat) => { if (!document) return; void exportManagerSalesPdf({ rows: [exportRow(view, document, activeReportCurrency)], tenantName: themeConfig?.tenantName || user?.tenantName || 'Empresa', tenantLogo: themeConfig?.logo, primaryColor: themeConfig?.colors?.primary, title: `Detalle · ${document.title || viewLabels[view]}`, fileBase: `manager-compra-${document.number || document.id}`, reportCurrency: activeReportCurrency, filterSummary, metrics, pdfFormat: format, pdfDesign: document.pdfDesign }); };

  return <div className="purchases-module min-w-0 space-y-5 overflow-x-hidden p-4 sm:p-6 md:p-8">
    <div className="flex min-w-0 flex-col gap-4 md:flex-row md:items-start md:justify-between"><div className="flex min-w-0 items-start gap-3"><div className="flex size-12 shrink-0 items-center justify-center rounded-2xl bg-primary/10 text-primary"><Truck className="size-6" /></div><div className="min-w-0"><h1 className="truncate text-3xl font-black uppercase italic tracking-tighter sm:text-4xl">Compras</h1><div className="mt-2 flex flex-wrap items-center gap-2"><Badge variant="outline" className="border-primary/20 bg-primary/10 text-[10px] font-black uppercase tracking-widest text-primary">{branches.length} sucursal(es) en el alcance</Badge><span className="text-xs text-muted-foreground">Referencia: {formatCurrencyDescriptor(activeReportCurrency)}</span></div></div></div><div className="flex shrink-0 flex-wrap gap-2"><Button variant="outline" className="rounded-xl" onClick={() => void query.refetch()} disabled={query.isFetching}><RefreshCw className={cn('mr-2 size-4', query.isFetching && 'animate-spin')} />Actualizar</Button><Button variant="outline" className="rounded-xl" onClick={() => void exportReport('xlsx')} disabled={exporting}>{exporting ? <Loader2 className="mr-2 size-4 animate-spin" /> : <Download className="mr-2 size-4" />}Exportar Excel</Button><PdfDownloadButton onDownload={(format) => { void exportReport(format); }} disabled={exporting} /></div></div>
    {sidebarCollapsed && <div className="manager-module-subnav flex min-w-0 gap-2 overflow-x-auto rounded-2xl border border-border/60 bg-muted/30 p-1.5">{MANAGER_PURCHASES_VIEWS.map((item) => <button key={item.id} type="button" onClick={() => changeView(item.id)} className={cn('flex-none rounded-xl px-3 py-2 text-[11px] font-black uppercase tracking-wide text-muted-foreground transition-colors hover:bg-card hover:text-foreground', view === item.id && 'bg-primary text-primary-foreground shadow-sm')}><span className="sm:hidden">{item.label.slice(0, 3)}</span><span className="hidden sm:inline">{item.label}</span></button>)}</div>}
    {view === 'overview' ? <PurchasesOverview metrics={metrics} reportCurrency={activeReportCurrency} /> : <><PurchaseFilters view={view} search={search} setSearch={(value) => { setSearch(value); setPage(1); }} status={status} setStatus={(value) => { setStatus(value); setPage(1); }} supplierType={supplierType} setSupplierType={(value) => { setSupplierType(value); setPage(1); }} dateFrom={dateFrom} setDateFrom={(value) => { setDateFrom(value); setPage(1); }} dateTo={dateTo} setDateTo={(value) => { setDateTo(value); setPage(1); }} statusOptions={activeStatusOptions} layoutMode={effectiveLayoutMode} setLayoutMode={setLayoutMode} /><PurchaseKpis view={view} metrics={metrics} reportCurrency={activeReportCurrency} />{query.isLoading ? <LoadingState /> : query.error ? <EmptyState title="No se pudo cargar la vista" description="Verifica el permiso Manager de Compras y vuelve a actualizar." /> : effectiveLayoutMode === 'cards' ? <PurchaseCards view={view} rows={displayRows} showBranch reportCurrency={activeReportCurrency} onDetail={openDetail} /> : <PurchaseTable view={view} rows={displayRows} columns={columns} sortState={columnSorts} onSort={changeColumnSort} onDetail={openDetail} /> }<Pagination page={response?.meta.page || page} totalPages={response?.meta.totalPages || 1} total={response?.meta.total || 0} pageSize={pageSize} onPageChange={setPage} onPageSizeChange={(value) => { setPageSize(value); setPage(1); }} /></>}
    <SalesDocumentDetailSheet document={panel} entity={detailEntity(view)} open={Boolean(selected)} onClose={() => { setSelected(null); setDetail(null); }} onGoToBranch={goToBranch} onWhatsApp={sendWhatsApp} hasWhatsApp={Boolean(supplierPhone)} onDownloadPdf={downloadDetail} />
  </div>;
}

function PurchasesOverview({ metrics, reportCurrency }: { metrics: Record<string, any>; reportCurrency: string }) { const cards = [['Proveedores', metrics.suppliers, Users, false], ['Órdenes de compra', metrics.orders, ClipboardList, false], ['Recepciones', metrics.receipts, PackageCheck, false], ['Facturas de proveedor', metrics.invoices, Receipt, false], ['Pagos realizados', metrics.payments, CreditCard, false], ['Gastos', metrics.expenses, WalletCards, false], ['Total ordenado', metrics.orderedAmount, Truck, true], ['Saldo a proveedores', metrics.supplierBalance, Banknote, true]] as const; return <div className="space-y-5"><div className="grid grid-cols-1 gap-4 sm:grid-cols-2 xl:grid-cols-4">{cards.map(([label, value, Icon, money]) => <Card key={label} className="rounded-2xl border-border/60 shadow-sm"><CardContent className="flex items-center gap-4 p-5"><div className="flex size-11 shrink-0 items-center justify-center rounded-xl bg-primary/10 text-primary"><Icon className="size-5" /></div><div className="min-w-0"><p className="text-[10px] font-black uppercase tracking-widest text-muted-foreground">{label}</p><p className="mt-1 truncate text-2xl font-black tracking-tight">{money ? formatMoney(value, label === 'Saldo a proveedores' ? metrics.supplierBalanceCurrency || reportCurrency : metrics.orderedAmountCurrency || reportCurrency) : formatNumber(value)}</p>{money && <p className="mt-1 text-[10px] text-muted-foreground">{formatCurrencyDescriptor(label === 'Saldo a proveedores' ? metrics.supplierBalanceCurrency || reportCurrency : metrics.orderedAmountCurrency || reportCurrency)}</p>}</div></CardContent></Card>)}</div><Card className="rounded-3xl border-primary/20 bg-primary/5"><CardHeader><CardTitle className="text-lg font-black uppercase italic tracking-tight">Lectura del abastecimiento</CardTitle></CardHeader><CardContent className="grid grid-cols-1 gap-4 text-sm md:grid-cols-4"><div><p className="text-muted-foreground">Sucursal con más órdenes</p><p className="mt-1 font-black">{metrics.topBranchName || 'Sin datos'}{metrics.topBranchCount ? ` · ${formatNumber(metrics.topBranchCount)}` : ''}</p></div><div><p className="text-muted-foreground">Facturado en referencia</p><p className="mt-1 font-black">{formatMoney(metrics.invoicedAmount, metrics.invoicedAmountCurrency || reportCurrency)}</p></div><div><p className="text-muted-foreground">Saldo pendiente</p><p className="mt-1 font-black">{formatMoney(metrics.invoiceBalance, metrics.invoiceBalanceCurrency || reportCurrency)}</p></div><div><p className="text-muted-foreground">Valoración</p><p className="mt-1 font-black">{metrics.valuationLabel || 'Valor histórico'}</p></div></CardContent></Card></div>; }

function PurchaseFilters({ view, search, setSearch, status, setStatus, supplierType, setSupplierType, dateFrom, setDateFrom, dateTo, setDateTo, statusOptions, layoutMode, setLayoutMode }: { view: ManagerPurchasesView; search: string; setSearch: (value: string) => void; status: string; setStatus: (value: string) => void; supplierType: string; setSupplierType: (value: string) => void; dateFrom: string; setDateFrom: (value: string) => void; dateTo: string; setDateTo: (value: string) => void; statusOptions: Array<{ value: string; label: string }>; layoutMode: LayoutMode; setLayoutMode: (value: LayoutMode) => void }) { return <Card className="rounded-3xl border-border/60 shadow-sm"><CardContent className="grid min-w-0 grid-cols-1 gap-3 p-4 md:grid-cols-2 xl:grid-cols-[minmax(220px,1.4fr)_minmax(150px,0.7fr)_minmax(150px,0.7fr)_minmax(150px,0.7fr)_auto] xl:items-end"><label className="min-w-0 space-y-1.5 text-xs font-bold text-muted-foreground"><span>Buscar</span><div className="relative"><Search className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2" /><Input value={search} onChange={(event) => setSearch(event.target.value)} placeholder={view === 'suppliers' ? 'Código, proveedor, RUC...' : 'Número, proveedor o referencia...'} className="pl-9" /></div></label>{view === 'suppliers' ? <label className="space-y-1.5 text-xs font-bold text-muted-foreground"><span>Tipo de proveedor</span><select value={supplierType} onChange={(event) => setSupplierType(event.target.value)} className="h-10 w-full rounded-xl border border-border bg-background px-3 text-sm font-normal"><option value="">Todos</option><option value="COMPANY">Empresas</option><option value="INDIVIDUAL">Particulares</option></select></label> : <label className="space-y-1.5 text-xs font-bold text-muted-foreground"><span>{view === 'payments' ? 'Método de pago' : 'Estado'}</span><select value={status} onChange={(event) => setStatus(event.target.value)} className="h-10 w-full rounded-xl border border-border bg-background px-3 text-sm font-normal"><option value="">Todos</option>{statusOptions.map((option) => <option key={option.value} value={option.value}>{option.label}</option>)}</select></label>}<DateInput label="Fecha desde" value={dateFrom} onChange={setDateFrom} /><DateInput label="Fecha hasta" value={dateTo} onChange={setDateTo} /><div className="flex items-center justify-end gap-1 rounded-xl border border-border/60 bg-muted/20 p-1"><Button type="button" variant={layoutMode === 'table' ? 'secondary' : 'ghost'} size="icon" className="size-9 rounded-lg" onClick={() => setLayoutMode('table')} aria-label="Vista tabla"><List className="size-4" /></Button><Button type="button" variant={layoutMode === 'cards' ? 'secondary' : 'ghost'} size="icon" className="size-9 rounded-lg" onClick={() => setLayoutMode('cards')} aria-label="Vista tarjetas"><LayoutGrid className="size-4" /></Button></div></CardContent></Card>; }
function DateInput({ label, value, onChange }: { label: string; value: string; onChange: (value: string) => void }) { return <label className="min-w-0 space-y-1.5 text-xs font-bold text-muted-foreground"><span>{label}</span><div className="relative"><CalendarDays className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2" /><Input type="date" value={value} onChange={(event) => onChange(event.target.value)} className="pl-9" /></div></label>; }

function PurchaseKpis({ view, metrics, reportCurrency }: { view: ManagerPurchasesView; metrics: Record<string, any>; reportCurrency: string }) { const cards = useMemo(() => { const total = Number(metrics.total || 0); if (view === 'suppliers') return [['Proveedores', formatNumber(total)], ['Empresas', formatNumber(metrics.companies)], ['Particulares', formatNumber(metrics.individuals)], ['Saldo', formatMoney(metrics.balance, reportCurrency)]]; if (view === 'invoices') return [['Facturas', formatNumber(total)], ['Total facturado', formatMoney(metrics.amount, metrics.amountCurrency || reportCurrency)], ['Pagado', formatMoney(metrics.paidTotal, metrics.amountCurrency || reportCurrency)], ['Saldo pendiente', formatMoney(metrics.pendingBalance, metrics.amountCurrency || reportCurrency)]]; return [['Registros', formatNumber(total)], ['Monto acumulado', formatMoney(metrics.amount, metrics.amountCurrency || reportCurrency)], ['Sucursal principal', metrics.topBranchName || 'Sin datos'], ['Registros principales', formatNumber(metrics.topBranchCount)]]; }, [metrics, reportCurrency, view]); return <div className="grid grid-cols-1 gap-3 sm:grid-cols-2 xl:grid-cols-4">{cards.map(([label, value]) => <div key={String(label)} className="rounded-2xl border border-border/60 bg-card p-4 shadow-sm"><p className="text-[10px] font-black uppercase tracking-widest text-muted-foreground">{label}</p><p className="mt-2 truncate text-xl font-black">{value || '0'}</p></div>)}</div>; }

function PurchaseTable({ view, rows, columns, sortState, onSort, onDetail }: { view: ManagerPurchasesView; rows: any[]; columns: PurchaseColumn[]; sortState: Record<string, ColumnSort>; onSort: (key: string, sort: ColumnSort) => void; onDetail: (row: any) => void }) { return <Card className="overflow-hidden rounded-3xl border-border/60 shadow-sm"><CardHeader className="border-b border-border/60"><CardTitle className="text-lg font-black uppercase italic tracking-tight">{viewLabels[view]}</CardTitle><p className="text-sm text-muted-foreground">Selecciona una fila para consultar el detalle, la auditoría y las acciones de la sucursal.</p></CardHeader><CardContent className="p-0">{rows.length ? <div className="sales-responsive-table overflow-x-auto"><Table className="min-w-[1080px]"><TableHeader><TableRow>{columns.map((column) => <TableHead key={column.key}><div className="flex items-center gap-1.5"><span>{column.label}</span><ColumnFilterMenu label={column.label} compact sort={sortState[`${view}:${column.key}`] || null} onSort={(sort) => onSort(column.key, sort)} sortType={column.sortType} /></div></TableHead>)}</TableRow></TableHeader><TableBody>{rows.map((row) => <TableRow key={row.id} className="cursor-pointer hover:bg-primary/[0.04]" onClick={() => onDetail(row)}>{columns.map((column) => <TableCell key={`${row.id}-${column.key}`} className={cn('max-w-72', column.numeric && 'text-right font-semibold')}>{column.render(row)}</TableCell>)}</TableRow>)}</TableBody></Table></div> : <EmptyState title="Sin registros" description="No hay información para el rubro, sucursal y filtros seleccionados." />}</CardContent></Card>; }

function PurchaseCards({ view, rows, showBranch, reportCurrency, onDetail }: { view: ManagerPurchasesView; rows: any[]; showBranch: boolean; reportCurrency: string; onDetail: (row: any) => void }) { if (!rows.length) return <EmptyState title="Sin registros" description="No hay información para el rubro, sucursal y filtros seleccionados." />; return <div className="grid grid-cols-1 gap-3 md:grid-cols-2 xl:grid-cols-3">{rows.map((row) => <Card key={row.id} className="cursor-pointer rounded-2xl border-border/60 shadow-sm transition-colors hover:border-primary/40" onClick={() => onDetail(row)}><CardContent className="space-y-3 p-5"><div className="flex items-start justify-between gap-3"><div className="min-w-0"><p className="truncate text-base font-black">{row.number || row.name || row.id.slice(0, 8)}</p><p className="text-xs text-muted-foreground">{row.supplierName || row.category || viewLabels[view]}</p>{showBranch && <PurchaseBranchLabel branchName={row.branchName} />}</div>{row.status && statusBadge(row.status)}</div><div className="grid grid-cols-2 gap-2 text-sm"><div><p className="text-xs text-muted-foreground">Fecha</p><p className="font-semibold">{formatDate(row.date || row.createdAt || row.nextInvoiceDate || row.nextExecutionDate)}</p></div><div><p className="text-xs text-muted-foreground">Monto original</p><MoneyPair row={row} reportCurrency={reportCurrency} /></div></div></CardContent></Card>)}</div>; }

function tableColumns(view: ManagerPurchasesView, showBranch: boolean, reportCurrency: string): PurchaseColumn[] { const text = (key: string, label: string, render: (row: any) => ReactNode, sortType: ColumnSortType = 'text'): PurchaseColumn => ({ key, label, render, getValue: (row) => row[key], sortType }); const money = (key: string, label: string, render: (row: any) => ReactNode): PurchaseColumn => ({ key, label, numeric: true, sortType: 'number', render, getValue: (row) => row[key] }); const columns: Record<ManagerPurchasesView, PurchaseColumn[]> = { overview: [], suppliers: [text('code', 'Código', (row) => row.code || '—'), text('name', 'Proveedor', (row) => <span className="font-semibold">{row.name}</span>), text('type', 'Tipo', (row) => statusLabel(row.type)), text('contact', 'Contacto', (row) => row.email || row.phone || '—'), money('balance', 'Saldo', (row) => formatMoney(row.balance, row.currency || reportCurrency)), text('status', 'Estado', (row) => statusBadge(row.status))], orders: [text('number', 'Orden', (row) => <span className="font-semibold text-primary">{row.number}</span>), text('date', 'Fecha', (row) => formatDate(row.date), 'date'), text('supplierName', 'Proveedor', (row) => row.supplierName), text('purchaseType', 'Tipo', (row) => statusLabel(row.purchaseType)), text('status', 'Estado', (row) => statusBadge(row.status)), text('expectedDelivery', 'Entrega', (row) => formatDate(row.expectedDelivery), 'date'), money('total', 'Total', (row) => <MoneyPair row={row} reportCurrency={reportCurrency} />)], receipts: [text('number', 'Recepción', (row) => <span className="font-semibold text-primary">{row.number}</span>), text('date', 'Fecha', (row) => formatDate(row.date), 'date'), text('purchaseOrderNumber', 'Orden', (row) => row.purchaseOrderNumber), text('supplierName', 'Proveedor', (row) => row.supplierName), text('status', 'Estado', (row) => statusBadge(row.status)), money('total', 'Total', (row) => <MoneyPair row={row} reportCurrency={reportCurrency} />), text('inventoryProcessedAt', 'Inventario', (row) => row.inventoryProcessedAt ? 'Procesado' : 'Pendiente')], invoices: [text('number', 'Factura', (row) => <span className="font-semibold text-primary">{row.number}</span>), text('date', 'Fecha', (row) => formatDate(row.date), 'date'), text('dueDate', 'Vencimiento', (row) => formatDate(row.dueDate), 'date'), text('supplierName', 'Proveedor', (row) => row.supplierName), text('status', 'Estado', (row) => statusBadge(row.status)), money('total', 'Total', (row) => <MoneyPair row={row} reportCurrency={reportCurrency} />), money('balance', 'Saldo', (row) => <MoneyPair row={row} field="balance" reportCurrency={reportCurrency} />)], recurring: [text('number', 'Registro', (row) => <span className="font-semibold text-primary">{row.number}</span>), text('nextInvoiceDate', 'Próxima', (row) => formatDate(row.nextInvoiceDate), 'date'), text('supplierName', 'Proveedor', (row) => row.supplierName), text('frequency', 'Frecuencia', (row) => statusLabel(row.frequency)), text('status', 'Estado', (row) => statusBadge(row.status)), money('total', 'Total', (row) => <MoneyPair row={row} reportCurrency={reportCurrency} />)], payments: [text('number', 'Pago', (row) => <span className="font-semibold text-primary">{row.number}</span>), text('date', 'Fecha', (row) => formatDate(row.date), 'date'), text('supplierName', 'Proveedor', (row) => row.supplierName), text('invoiceNumber', 'Factura', (row) => row.invoiceNumber), text('method', 'Método', (row) => statusLabel(row.method)), text('reference', 'Referencia', (row) => row.reference || '—'), money('amount', 'Monto', (row) => <MoneyPair row={row} field="amount" reportCurrency={reportCurrency} />)], credits: [text('number', 'Crédito', (row) => <span className="font-semibold text-primary">{row.number}</span>), text('date', 'Fecha', (row) => formatDate(row.date), 'date'), text('supplierName', 'Proveedor', (row) => row.supplierName), text('invoiceNumber', 'Factura', (row) => row.invoiceNumber), text('status', 'Estado', (row) => statusBadge(row.status)), text('reason', 'Motivo', (row) => row.reason || '—'), money('total', 'Total', (row) => <MoneyPair row={row} reportCurrency={reportCurrency} />)], expenses: [text('number', 'Gasto', (row) => <span className="font-semibold text-primary">{row.number}</span>), text('date', 'Fecha', (row) => formatDate(row.date), 'date'), text('supplierName', 'Proveedor', (row) => row.supplierName || row.paidTo || '—'), text('category', 'Categoría', (row) => row.category || '—'), text('description', 'Descripción', (row) => row.description || '—'), text('status', 'Estado', (row) => statusBadge(row.status)), money('amount', 'Monto', (row) => <MoneyPair row={row} field="amount" reportCurrency={reportCurrency} />)], recurringexpenses: [text('number', 'Registro', (row) => <span className="font-semibold text-primary">{row.number}</span>), text('nextExecutionDate', 'Próxima', (row) => formatDate(row.nextExecutionDate), 'date'), text('supplierName', 'Proveedor', (row) => row.supplierName || '—'), text('category', 'Categoría', (row) => row.category || '—'), text('frequency', 'Frecuencia', (row) => statusLabel(row.frequency)), text('status', 'Estado', (row) => statusBadge(row.status)), money('amount', 'Monto', (row) => <MoneyPair row={row} field="amount" reportCurrency={reportCurrency} />)], requests: [text('number', 'Solicitud', (row) => <span className="font-semibold text-primary">{row.number}</span>), text('date', 'Fecha', (row) => formatDate(row.date), 'date'), text('requiredDate', 'Requerida', (row) => formatDate(row.requiredDate), 'date'), text('supplierName', 'Proveedor', (row) => row.supplierName), text('priority', 'Prioridad', (row) => statusLabel(row.priority)), text('status', 'Estado', (row) => statusBadge(row.status)), text('warehouseName', 'Bodega', (row) => row.warehouseName)], management: [text('number', 'Gestión', (row) => <span className="font-semibold text-primary">{row.number}</span>), text('date', 'Fecha', (row) => formatDate(row.date), 'date'), text('supplierName', 'Proveedor', (row) => row.supplierName), text('quotationNumber', 'Cotización', (row) => row.quotationNumber || '—'), text('status', 'Estado', (row) => statusBadge(row.status)), text('expectedDelivery', 'Entrega', (row) => formatDate(row.expectedDelivery), 'date'), money('total', 'Total', (row) => <MoneyPair row={row} reportCurrency={reportCurrency} />)], supplierprices: [text('date', 'Fecha', (row) => formatDate(row.date), 'date'), text('supplierName', 'Proveedor', (row) => row.supplierName), text('productId', 'Producto', (row) => row.productId || '—'), text('description', 'Descripción', (row) => row.description || '—'), money('unitPrice', 'Precio', (row) => <MoneyPair row={row} field="unitPrice" reportCurrency={reportCurrency} />), text('notes', 'Notas', (row) => row.notes || '—')] }; if (showBranch) columns[view].push(text('branchName', 'Sucursal', (row) => <span className="font-semibold text-primary">{row.branchName || 'Sucursal'}</span>)); return columns[view]; }

function sortRows(rows: any[], columns: PurchaseColumn[], sortState: Record<string, ColumnSort>, view: ManagerPurchasesView) { const active = columns.find((column) => sortState[`${view}:${column.key}`]); const direction = active ? sortState[`${view}:${active.key}`] : null; if (!active || !direction) return rows; return [...rows].sort((a, b) => compareValues(active.getValue(a), active.getValue(b), active.sortType) * (direction === 'asc' ? 1 : -1)); }
function compareValues(a: unknown, b: unknown, type?: ColumnSortType) { if (type === 'number') return Number(a || 0) - Number(b || 0); if (type === 'date') return new Date(String(a || '')).getTime() - new Date(String(b || '')).getTime(); return String(a ?? '').localeCompare(String(b ?? ''), 'es', { sensitivity: 'base', numeric: true }); }
function purchaseRateSourceLabel(value: unknown) { return ({ TRANSACTION: 'Tasa de la operación', HISTORICAL: 'Tasa histórica', CURRENT_CONFIGURATION: 'Tasa vigente por falta de histórico', SAME_CURRENCY: 'Misma moneda' } as Record<string, string>)[String(value || '').toUpperCase()] || String(value || 'Tasa aplicada'); }
function purchaseRateSubtext(row: any) { if (!row.reportRateLabel) return 'Sin tasa de conversión'; return `${row.reportRateLabel} · ${purchaseRateSourceLabel(row.reportRateSource)} · ${formatDate(row.reportRateEffectiveAt || row.date || row.createdAt || row.nextInvoiceDate || row.nextExecutionDate)}`; }
function MoneyPair({ row, field = 'total', reportCurrency }: { row: any; field?: string; reportCurrency: string }) { const suffix = field.charAt(0).toUpperCase() + field.slice(1); const original = row[field]; const report = row[`report${suffix}`] ?? (field === 'total' ? row.reportTotal : field === 'amount' ? row.reportAmount : field === 'balance' ? row.reportBalance : undefined); return <div className="min-w-[128px]"><p className="font-black tabular-nums">{formatMoney(original, row.currency || 'NIO', true)}</p>{report != null && <p className="mt-0.5 text-[10px] font-semibold tabular-nums text-primary">≈ {formatMoney(report, reportCurrency, true)}</p>}<p className="mt-0.5 text-[9px] font-semibold leading-3 text-muted-foreground">{purchaseRateSubtext(row)}</p></div>; }
function buildPurchasePanel(document: any, reportCurrency: string, history: any[]): SalesDocumentPanelData { const field = document.amount != null ? 'amount' : document.unitPrice != null && document.total == null ? 'unitPrice' : document.balance != null && document.total == null ? 'balance' : 'total'; const original = document[field]; const report = document.reportTotal ?? document.reportAmount ?? document.reportBalance; const originalLabel = formatMoney(original, document.currency || 'NIO', true); const reportLabel = report == null ? '' : `≈ ${formatMoney(report, reportCurrency, true)}`; return { id: document.id, number: document.number || String(document.id).slice(0, 8), title: document.title || 'Registro de compras', customerName: document.supplierName || 'Proveedor no definido', status: document.status || 'PENDING', totalLabel: reportLabel ? `${originalLabel} · ${reportLabel}` : originalLabel, summaryDetails: [{ label: 'Sucursal', value: document.branchName || 'Sucursal' }, { label: 'Moneda original', value: formatCurrencyDescriptor(document.currency || 'NIO') }, ...(document.reportRateLabel ? [{ label: 'Tasa aplicada', value: document.reportRateLabel }] : [])], metadata: [{ label: 'Fecha', value: formatDate(document.date || document.createdAt || document.nextInvoiceDate || document.nextExecutionDate, true) }, { label: 'Rubro', value: document.businessUnitName || '—' }, ...(document.dueDate ? [{ label: 'Vencimiento', value: formatDate(document.dueDate) }] : []), ...(document.expectedDelivery ? [{ label: 'Entrega esperada', value: formatDate(document.expectedDelivery) }] : []), ...(document.method ? [{ label: 'Método', value: statusLabel(document.method) }] : [])], lines: (document.items || []).map((item: any, index: number) => ({ id: item.id || `${document.id}-${index}`, description: item.description || item.name || 'Artículo sin descripción', quantity: Number(item.quantity || item.quantityProposed || item.quantityReceived || 0), unitPriceLabel: item.unitPrice != null ? formatMoney(item.unitPrice, document.currency || 'NIO') : undefined, totalLabel: item.total != null ? formatMoney(item.total, document.currency || 'NIO') : undefined })), notes: document.notes || document.description || document.justification, reason: document.reason, history }; }
function detailEntity(view: ManagerPurchasesView) { return view === 'recurringexpenses' ? 'RECURRING_EXPENSE' : view === 'recurring' ? 'RECURRING_SUPPLIER_INVOICE' : view === 'suppliers' ? 'SUPPLIER' : view === 'orders' ? 'PURCHASE_ORDER' : view === 'receipts' ? 'PURCHASE_RECEIPT' : view === 'invoices' ? 'SUPPLIER_INVOICE' : view === 'payments' ? 'PAYMENT_MADE' : view === 'credits' ? 'SUPPLIER_CREDIT' : view === 'expenses' ? 'EXPENSE' : view === 'requests' ? 'PURCHASE_REQUEST' : view === 'management' ? 'PURCHASE_MANAGEMENT' : 'SUPPLIER_PRICE'; }
function exportRow(view: ManagerPurchasesView, row: any, reportCurrency: string) { const field = row.amount != null ? 'amount' : row.unitPrice != null && row.total == null ? 'unitPrice' : row.balance != null && row.total == null ? 'balance' : 'total'; const report = row[`report${field.charAt(0).toUpperCase() + field.slice(1)}`] ?? (field === 'total' ? row.reportTotal : field === 'amount' ? row.reportAmount : field === 'balance' ? row.reportBalance : undefined); return { Vista: viewLabels[view], Identificador: row.number || row.name || row.id, Fecha: formatDate(row.date || row.createdAt || row.nextInvoiceDate || row.nextExecutionDate), Proveedor: row.supplierName || '', Estado: statusLabel(row.status), 'Monto original': row[field] == null ? '—' : formatMoney(row[field], row.currency || 'NIO', true), Equivalencia: report == null ? '—' : formatMoney(report, reportCurrency, true), 'Tasa aplicada': row.reportRateLabel || '—', Sucursal: row.branchName || '', Rubro: row.businessUnitName || '' }; }
function Pagination({ page, totalPages, total, pageSize, onPageChange, onPageSizeChange }: { page: number; totalPages: number; total: number; pageSize: number; onPageChange: (page: number) => void; onPageSizeChange: (size: number) => void }) { return <div className="flex flex-col gap-3 text-sm text-muted-foreground sm:flex-row sm:items-center sm:justify-between"><span>{formatNumber(total)} registro(s)</span><div className="flex items-center gap-2"><select value={pageSize} onChange={(event) => onPageSizeChange(Number(event.target.value))} className="h-9 rounded-lg border border-border bg-background px-2 text-xs"><option value={25}>25 / página</option><option value={50}>50 / página</option><option value={100}>100 / página</option></select><Button variant="outline" size="icon" className="size-9 rounded-lg" onClick={() => onPageChange(Math.max(1, page - 1))} disabled={page <= 1}><ChevronLeft className="size-4" /></Button><span className="min-w-20 text-center text-xs font-semibold">Página {page} de {totalPages}</span><Button variant="outline" size="icon" className="size-9 rounded-lg" onClick={() => onPageChange(Math.min(totalPages, page + 1))} disabled={page >= totalPages}><ChevronRight className="size-4" /></Button></div></div>; }
function LoadingState() { return <div className="flex min-h-48 items-center justify-center text-sm text-muted-foreground"><RefreshCw className="mr-2 size-5 animate-spin" />Cargando compras...</div>; }
function EmptyState({ title, description }: { title: string; description: string }) { return <div className="rounded-3xl border border-dashed border-border p-10 text-center"><p className="font-black">{title}</p><p className="mt-1 text-sm text-muted-foreground">{description}</p></div>; }
