import { useEffect, useMemo, useState } from 'react';
import { useMutation } from '@tanstack/react-query';
import * as XLSX from 'xlsx';
import type { Worksheet } from 'exceljs';
import { toast } from 'sonner';
import { AlertTriangle, ArrowLeft, CheckCircle2, Download, FileSpreadsheet, ImageIcon, Info, Loader2, PackagePlus, Upload, Warehouse } from 'lucide-react';
import { useTenantQuery } from '../../hooks/useTenantQuery';
import {
  enterpriseGroupsService,
  type ManagerInventoryImportPreview,
  type ManagerInventoryImportOptions,
} from '../../services/enterprise-groups.service';
import { storageService } from '../../services/storage.service';
import { extractProductImageArchive, PRODUCT_IMAGE_ARCHIVE_EXTENSIONS } from '../../utils/product-image-archive';
import { Badge } from '../ui/badge';
import { Button } from '../ui/button';
import { Card, CardContent } from '../ui/card';
import { Input } from '../ui/input';

type Currency = 'NIO' | 'USD';
type StockMode = 'SET' | 'ADD';
type BusinessUnitOption = { id: string; name: string; isActive?: boolean };

type Props = {
  onBack: () => void;
  groupId: string;
  businessUnitId?: string;
  businessUnits: BusinessUnitOption[];
  onImported: () => void;
};

const numberFormat = new Intl.NumberFormat('es-NI', { maximumFractionDigits: 2 });
const formatNumber = (value: unknown) => numberFormat.format(Number(value || 0));
const statusLabels: Record<string, string> = {
  NUEVO_PRODUCTO: 'Producto nuevo',
  CREAR_ESPEJO: 'Crear espejo',
  PRODUCTO_EXISTENTE: 'Producto existente',
};

const rowCode = (row: Record<string, unknown>) => String(row['Código / SKU'] ?? row.Código ?? row.Codigo ?? row.code ?? row.codigo ?? row.SKU ?? row.sku ?? '').trim();

const safeFileNamePart = (value: string) =>
  value
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-zA-Z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .toLowerCase() || 'rubro';

function readSpreadsheetRows(file: File) {
  return file.arrayBuffer().then((buffer) => {
    const workbook = XLSX.read(buffer, { type: 'array' });
    const normalizeSheetName = (value: string) => value.normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim().toLowerCase();
    const readSheet = (name?: string) => name ? XLSX.utils.sheet_to_json<Record<string, unknown>>(workbook.Sheets[name], { defval: '' }) : [];
    const productSheetName = workbook.SheetNames.find((name) => normalizeSheetName(name) === 'productos');
    const distributionSheetName = workbook.SheetNames.find((name) => ['distribucion', 'asignaciones', 'ubicaciones'].includes(normalizeSheetName(name)));
    const products = readSheet(productSheetName);
    const distributions = readSheet(distributionSheetName);
    const normalizeKey = (value: unknown) => String(value ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-zA-Z0-9]/g, '').toLowerCase();
    const readValue = (row: Record<string, unknown>, aliases: string[]) => aliases.map((alias) => row[alias] ?? row[Object.keys(row).find((key) => normalizeKey(key) === normalizeKey(alias)) || '']).find((value) => value !== undefined && value !== '');
    const productByCode = new Map<string, Record<string, unknown>>();
    products.forEach((product) => {
      const code = String(readValue(product, ['Código / SKU', 'Código', 'Codigo', 'SKU', 'code']) ?? '').trim();
      if (code) productByCode.set(normalizeKey(code), product);
    });
    if (productSheetName && distributionSheetName) {
      const rows = distributions.map((distribution) => {
        const code = String(readValue(distribution, ['Código / SKU', 'Código', 'Codigo', 'SKU', 'code']) ?? '').trim();
        return { ...(productByCode.get(normalizeKey(code)) || {}), ...distribution };
      });
      return { rows, productRows: products.length, distributionRows: distributions.length, format: 'two-sheet' as const };
    }
    const firstSheet = workbook.SheetNames[0];
    return { rows: readSheet(firstSheet), productRows: 0, distributionRows: 0, format: 'legacy' as const };
  });
}

export function ManagerInventoryImportView({ onBack, groupId, businessUnitId, businessUnits, onImported }: Props) {
  const importBusinessUnitId = businessUnitId || '';
  const [currency, setCurrency] = useState<Currency>('NIO');
  const [stockMode, setStockMode] = useState<StockMode>('SET');
  const [exchangeRate, setExchangeRate] = useState('');
  const [rows, setRows] = useState<Record<string, unknown>[]>([]);
  const [fileName, setFileName] = useState('');
  const [sheetSummary, setSheetSummary] = useState<{ productRows: number; distributionRows: number; format: 'two-sheet' | 'legacy' } | null>(null);
  const [preview, setPreview] = useState<ManagerInventoryImportPreview | null>(null);
  const [imageArchiveFileName, setImageArchiveFileName] = useState('');
  const [imageArchiveEntries, setImageArchiveEntries] = useState<Map<string, File>>(new Map());
  const [imageArchiveProcessing, setImageArchiveProcessing] = useState(false);

  const optionsQuery = useTenantQuery(
    ['manager-inventory-import-options', groupId, importBusinessUnitId || ''],
    (signal) => enterpriseGroupsService.getSharedInventoryImportOptions(groupId, importBusinessUnitId || '', signal),
    { enabled: Boolean(groupId && importBusinessUnitId) },
  );
  const options = optionsQuery.data as ManagerInventoryImportOptions | undefined;

  useEffect(() => {
    setRows([]);
    setFileName('');
    setSheetSummary(null);
    setPreview(null);
    setExchangeRate('');
    setImageArchiveFileName('');
    setImageArchiveEntries(new Map());
  }, [importBusinessUnitId]);

  const locationsByBranch = useMemo(() => {
    const result = new Map<string, number>();
    (options?.locations || []).forEach((location) => result.set(location.branchId, (result.get(location.branchId) || 0) + 1));
    return result;
  }, [options?.locations]);

  const targetBaseCurrencies = useMemo(() => [...new Set((options?.branches || []).map((branch) => String(branch.baseCurrency || 'NIO').trim().toUpperCase()))], [options?.branches]);
  const requiresManualExchangeRate = targetBaseCurrencies.some((baseCurrency) => baseCurrency !== currency);
  const parsedExchangeRate = Number(exchangeRate.replace(',', '.'));
  const hasValidExchangeRate = !requiresManualExchangeRate || (Number.isFinite(parsedExchangeRate) && parsedExchangeRate > 0);
  const targetBaseCurrencyLabel = targetBaseCurrencies.length ? targetBaseCurrencies.join(' / ') : 'la moneda base de las sucursales';

  const requestBody = useMemo(() => ({
    businessUnitId: importBusinessUnitId,
    currency,
    stockMode,
    exchangeRate: Number.isFinite(parsedExchangeRate) && parsedExchangeRate > 0 ? parsedExchangeRate : undefined,
    rows,
  }), [importBusinessUnitId, currency, stockMode, parsedExchangeRate, rows]);

  const previewMutation = useMutation({
    mutationFn: () => enterpriseGroupsService.previewSharedInventory(groupId, requestBody),
    onSuccess: (result) => setPreview(result),
    onError: (error: Error) => toast.error(error.message),
  });

  const importMutation = useMutation({
    mutationFn: async () => {
      if (!imageArchiveEntries.size) return enterpriseGroupsService.importSharedInventory(groupId, requestBody);
      const imageUrlByCode = new Map<string, string>();
      const uploadWarnings: string[] = [];
      const importedCodes = new Set(rows.map((row) => rowCode(row).toLowerCase()).filter(Boolean));
      for (const [code, imageFile] of imageArchiveEntries) {
        if (!importedCodes.has(code)) continue;
        try {
          const uploaded = await storageService.uploadFile('product-image', imageFile, { folder: 'manager-import' });
          imageUrlByCode.set(code, uploaded.url);
        } catch {
          uploadWarnings.push(code);
        }
      }
      if (uploadWarnings.length) toast.warning(`${uploadWarnings.length} imagen(es) no pudieron cargarse; la importación continuará sin esas imágenes.`);
      const rowsWithImages = rows.map((row) => {
        const imageUrl = imageUrlByCode.get(rowCode(row).toLowerCase());
        return imageUrl ? { ...row, imageUrl } : row;
      });
      return enterpriseGroupsService.importSharedInventory(groupId, { ...requestBody, rows: rowsWithImages });
    },
    onSuccess: (result: any) => {
      toast.success(`Importación aplicada: ${result.stockUpdated || 0} ubicación(es), ${result.productsCreated || 0} espejo(s) y ${result.locationsCreated || 0} registro(s) de stock`);
      onBack();
      onImported();
    },
    onError: (error: Error) => toast.error(error.message),
  });

  const onFile = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    try {
      const parsed = await readSpreadsheetRows(file);
      if (!parsed.rows.length) {
        toast.error(parsed.format === 'two-sheet' ? 'La hoja Distribución no contiene filas para importar' : 'El archivo no contiene filas para importar');
        return;
      }
      setRows(parsed.rows);
      setFileName(file.name);
      setSheetSummary(parsed);
      setPreview(null);
    } catch (error) {
      toast.error(error instanceof Error ? error.message : 'No se pudo leer la plantilla');
    } finally {
      event.target.value = '';
    }
  };

  const onImageArchive = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    if (!PRODUCT_IMAGE_ARCHIVE_EXTENSIONS.test(file.name)) {
      toast.error('Selecciona un archivo ZIP o RAR válido');
      event.target.value = '';
      return;
    }
    setImageArchiveProcessing(true);
    try {
      const entries = await extractProductImageArchive(file);
      setImageArchiveEntries(entries);
      setImageArchiveFileName(file.name);
      setPreview(null);
      toast.success(`${entries.size} imagen(es) encontradas; se asociarán por nombre de SKU.`);
    } catch (error) {
      toast.error(error instanceof Error ? error.message : 'No se pudo leer el archivo de imágenes');
    } finally {
      setImageArchiveProcessing(false);
      event.target.value = '';
    }
  };

  const downloadTemplate = async () => {
    const activeLocations = options?.locations || [];
    if (!activeLocations.length) {
      toast.error('No hay ubicaciones activas disponibles para generar la plantilla');
      return;
    }

    try {
      const { Workbook } = (await import('exceljs')).default;
      const workbook = new Workbook();
      workbook.creator = 'NovaHub ERP';
      workbook.created = new Date();

      const activeBranches = (options?.branches || []).map((branch) => branch.name).filter(Boolean);
      const uniquePhysicalLocations = Array.from(new Map(activeLocations.map((location) => [location.warehouseId, location])).values());
      const uniqueLocationLabels = [...new Set(activeLocations.map((location) => location.selectionLabel || location.name).filter(Boolean))];

      const products = workbook.addWorksheet('Productos');
      products.columns = [
        { header: 'Código / SKU', key: 'code', width: 20 },
        { header: 'Nombre', key: 'name', width: 30 },
        { header: 'Categoría', key: 'category', width: 24 },
        { header: 'Unidad', key: 'unit', width: 14 },
        { header: 'Costo', key: 'cost', width: 16 },
      ];
      products.addRow({ code: '', name: '', category: '', unit: 'unidad', cost: '' });

      const distribution = workbook.addWorksheet('Distribución');
      distribution.columns = [
        { header: 'Código / SKU', key: 'code', width: 20 },
        { header: 'Tipo de ubicación', key: 'type', width: 20 },
        { header: 'Sucursal vinculada / catálogo', key: 'branch', width: 32 },
        { header: 'Ubicación destino', key: 'location', width: 48 },
        { header: 'Stock inicial', key: 'stock', width: 16 },
        { header: 'Stock mínimo', key: 'minStock', width: 16 },
        { header: 'Registrar catálogo', key: 'registerCatalog', width: 20 },
      ];
      uniquePhysicalLocations.forEach((location) => {
        distribution.addRow({
          code: '',
          type: location.type === 'ALMACEN' ? 'ALMACÉN' : 'BODEGA',
          branch: location.type === 'ALMACEN' ? '' : location.branchName,
          location: location.selectionLabel || location.name,
          stock: 0,
          minStock: 0,
          registerCatalog: 'SI',
        });
      });

      const locationRows = uniquePhysicalLocations.map((location) => {
        const isCorporate = Boolean(location.isCorporate || location.scopeType === 'BUSINESS_UNIT');
        return {
          'Sucursal propietaria': isCorporate ? '—' : location.branchName,
          Tipo: isCorporate ? 'Almacén corporativo' : 'Bodega de sucursal',
          Ubicación: location.name,
          Dirección: location.location || '',
          Alcance: isCorporate ? 'Fuera de las sucursales · pertenece al rubro' : 'Dentro de la sucursal',
          Activa: location.active ? 'SI' : 'NO',
        };
      });
      const locationsSheet = workbook.addWorksheet('Ubicaciones activas');
      locationsSheet.columns = [
        { header: 'Sucursal propietaria', key: 'ownerBranch', width: 26 },
        { header: 'Tipo', key: 'type', width: 25 },
        { header: 'Ubicación', key: 'location', width: 28 },
        { header: 'Dirección', key: 'address', width: 24 },
        { header: 'Alcance', key: 'scope', width: 42 },
        { header: 'Activa', key: 'active', width: 12 },
      ];
      locationRows.forEach((row) => locationsSheet.addRow({
        ownerBranch: row['Sucursal propietaria'],
        type: row.Tipo,
        location: row.Ubicación,
        address: row.Dirección,
        scope: row.Alcance,
        active: row.Activa,
      }));

      const guide = workbook.addWorksheet('Guía de llenado');
      [
        ['GUÍA DE LLENADO · IMPORTACIÓN POR RUBRO'],
        ['Productos contiene cada SKU una sola vez. Distribución repite únicamente el SKU para asignar stock a varias ubicaciones.'],
        ['Las listas desplegables se cargan con las sucursales y ubicaciones activas al momento de descargar este archivo.'],
        ['Campo', 'Hoja', 'Regla'],
        ['Código / SKU', 'Productos y Distribución', 'Obligatorio. Relaciona ambas hojas; no escribas IDs.'],
        ['Nombre', 'Productos', 'Obligatorio cuando el producto todavía no existe en el rubro.'],
        ['Costo', 'Productos', 'Obligatorio y único para el mismo SKU en todas sus ubicaciones.'],
        ['Tipo de ubicación', 'Distribución', 'BODEGA = ubicación dentro de una sucursal. ALMACÉN = almacén corporativo fuera de las sucursales.'],
        ['Sucursal vinculada / catálogo', 'Distribución', 'Para BODEGA es obligatoria y corresponde a su sucursal propietaria. Para ALMACÉN se deja vacía: el sistema toma automáticamente todas las sucursales autorizadas para ese almacén.'],
        ['Ubicación destino', 'Distribución', 'Selecciona una opción del dropdown. Las opciones no muestran IDs; incluyen el contexto necesario para evitar nombres repetidos.'],
        ['Stock inicial', 'Distribución', 'Cantidad final o cantidad a sumar según el modo seleccionado. Puede ser 0.'],
        ['Stock mínimo', 'Distribución', 'Nivel mínimo de inventario para esa relación de stock.'],
        ['Registrar catálogo', 'Distribución', 'SI/NO. El backend vuelve a validar la ubicación, su alcance y su estado activo.'],
        ['Almacén corporativo', 'Ubicaciones activas', 'Se muestra una sola vez, fuera de sucursales. Las sucursales que puede abastecer ya están configuradas en el sistema y no se repiten en la plantilla.'],
        ['Imágenes', 'Importación', 'Opcional. Carga un ZIP o RAR con JPG/PNG nombrados exactamente como el SKU; la asociación se revisa por nombre antes de confirmar.'],
      ].forEach((row) => guide.addRow(row));
      guide.getColumn(1).width = 34;
      guide.getColumn(2).width = 28;
      guide.getColumn(3).width = 105;

      const catalogs = workbook.addWorksheet('Catálogos');
      catalogs.state = 'veryHidden';
      catalogs.getCell('A1').value = 'Sucursales activas';
      catalogs.getCell('B1').value = 'Ubicaciones activas';
      activeBranches.forEach((name, index) => { catalogs.getCell(index + 2, 1).value = name; });
      uniqueLocationLabels.forEach((label, index) => { catalogs.getCell(index + 2, 2).value = label; });
      workbook.definedNames.add('SucursalesActivas', `'Catálogos'!$A$2:$A$${Math.max(activeBranches.length + 1, 2)}`);
      workbook.definedNames.add('UbicacionesActivas', `'Catálogos'!$B$2:$B$${Math.max(uniqueLocationLabels.length + 1, 2)}`);

      const headerStyle = {
        font: { bold: true, color: { argb: 'FFFFFFFF' } },
        fill: { type: 'pattern' as const, pattern: 'solid' as const, fgColor: { argb: 'FF087F5B' } },
        alignment: { vertical: 'middle' as const, wrapText: true },
      };
      const styleHeader = (sheet: Worksheet) => {
        sheet.getRow(1).height = 30;
        sheet.getRow(1).eachCell((cell) => { cell.style = headerStyle; });
        sheet.views = [{ state: 'frozen', ySplit: 1 }];
        sheet.autoFilter = { from: 'A1', to: `${String.fromCharCode(64 + sheet.columnCount)}${Math.max(sheet.rowCount, 2)}` };
      };
      [products, distribution, locationsSheet].forEach(styleHeader);
      guide.getRow(1).font = { bold: true, color: { argb: 'FF087F5B' } };
      guide.getRow(1).height = 28;
      guide.views = [{ state: 'frozen', ySplit: 3 }];

      for (let rowNumber = 2; rowNumber <= Math.max(distribution.rowCount, 2); rowNumber += 1) {
        distribution.getCell(rowNumber, 2).dataValidation = { type: 'list', allowBlank: false, formulae: ['"BODEGA,ALMACÉN"'], showErrorMessage: true, errorTitle: 'Tipo no válido', error: 'Selecciona BODEGA o ALMACÉN.' };
        distribution.getCell(rowNumber, 3).dataValidation = { type: 'list', allowBlank: true, formulae: ['=SucursalesActivas'], showErrorMessage: true, errorTitle: 'Sucursal no válida', error: 'Selecciona una sucursal activa para una BODEGA; déjala vacía para un ALMACÉN.' };
        distribution.getCell(rowNumber, 4).dataValidation = { type: 'list', allowBlank: false, formulae: ['=UbicacionesActivas'], showErrorMessage: true, errorTitle: 'Ubicación no válida', error: 'Selecciona una ubicación activa.' };
        distribution.getCell(rowNumber, 5).dataValidation = { type: 'decimal', operator: 'greaterThanOrEqual', allowBlank: false, formulae: [0], showErrorMessage: true, errorTitle: 'Cantidad no válida', error: 'Ingresa un número mayor o igual que cero.' };
        distribution.getCell(rowNumber, 6).dataValidation = { type: 'decimal', operator: 'greaterThanOrEqual', allowBlank: false, formulae: [0], showErrorMessage: true, errorTitle: 'Mínimo no válido', error: 'Ingresa un número mayor o igual que cero.' };
        distribution.getCell(rowNumber, 7).dataValidation = { type: 'list', allowBlank: false, formulae: ['"SI,NO"'], showErrorMessage: true, errorTitle: 'Opción no válida', error: 'Selecciona SI o NO.' };
      }
      products.getCell(2, 5).dataValidation = { type: 'decimal', operator: 'greaterThanOrEqual', allowBlank: true, formulae: [0], showErrorMessage: true, errorTitle: 'Costo no válido', error: 'Ingresa un costo mayor o igual que cero.' };

      const buffer = await workbook.xlsx.writeBuffer();
      const blob = new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
      const url = URL.createObjectURL(blob);
      const anchor = document.createElement('a');
      anchor.href = url;
      anchor.download = `plantilla-importacion-${safeFileNamePart(selectedBusinessUnitName)}.xlsx`;
      anchor.click();
      window.setTimeout(() => URL.revokeObjectURL(url), 1000);
    } catch (error) {
      toast.error(error instanceof Error ? error.message : 'No se pudo generar la plantilla Excel');
    }
  };

  const validForImport = Boolean(preview && !preview.errors.length && preview.summary.validRows > 0);
  const selectedBusinessUnitName = businessUnits.find((unit) => unit.id === importBusinessUnitId)?.name || '—';

  return <section className="min-w-0 space-y-6">
    <div className="flex min-w-0 flex-col gap-4 rounded-[28px] border border-border/60 bg-card p-4 shadow-sm sm:p-6 md:flex-row md:items-center md:justify-between md:p-7">
      <div className="flex min-w-0 items-start gap-4">
        <div className="flex size-12 shrink-0 items-center justify-center rounded-2xl bg-primary/10 text-primary"><PackagePlus className="size-6" /></div>
        <div className="min-w-0">
          <p className="text-[10px] font-black uppercase tracking-[0.2em] text-primary">Subvista de productos · carga masiva</p>
          <h1 className="mt-1 text-2xl font-black uppercase italic tracking-tight sm:text-3xl">Importar inventario por rubro</h1>
          <p className="mt-2 max-w-3xl text-sm leading-6 text-muted-foreground">Carga productos una sola vez y distribuye sus existencias entre bodegas y almacenes activos. El archivo se previsualiza, normaliza y valida antes de confirmar.</p>
        </div>
      </div>
      <Button type="button" variant="outline" className="w-full shrink-0 rounded-xl md:w-auto" onClick={onBack}><ArrowLeft className="mr-2 size-4" />Volver a productos</Button>
    </div>

    <div className="overflow-hidden rounded-[28px] border border-border/60 bg-card shadow-sm">
      <div className="min-h-0 overflow-y-auto p-4 sm:p-6 md:p-8">
      <div className="mb-6 flex min-w-0 items-start gap-3 border-b border-border/60 pb-5">
        <div className="min-w-0"><p className="text-xs font-black uppercase tracking-widest text-muted-foreground">Configuración de la importación</p><p className="mt-1 text-sm leading-6 text-muted-foreground">La plantilla se valida contra las sucursales, bodegas y almacenes activos del rubro. Las bodegas viven dentro de una sucursal; los almacenes corporativos viven fuera de ellas. En un ALMACÉN la sucursal se resuelve automáticamente con la configuración vigente del sistema.</p></div>
      </div>

      {!importBusinessUnitId && <div className="rounded-2xl border border-amber-500/30 bg-amber-500/10 p-4 text-sm text-amber-700 dark:text-amber-300">Selecciona el rubro de importación para cargar sus ubicaciones activas.</div>}
      {importBusinessUnitId && <div className="space-y-5">
        <div className="grid min-w-0 grid-cols-1 gap-3 lg:grid-cols-3">
          <label className="min-w-0 space-y-1.5 text-xs font-bold text-muted-foreground"><span>Moneda del archivo</span><select value={currency} onChange={(event) => { setCurrency(event.target.value as Currency); setExchangeRate(''); setPreview(null); }} className="h-10 w-full min-w-0 rounded-xl border border-border bg-background px-3 text-sm font-normal text-foreground"><option value="NIO">Córdobas (NIO)</option><option value="USD">Dólares (USD)</option></select></label>
          <label className="min-w-0 space-y-1.5 text-xs font-bold text-muted-foreground"><span>Modo de stock</span><select value={stockMode} onChange={(event) => { setStockMode(event.target.value as StockMode); setPreview(null); }} className="h-10 w-full min-w-0 rounded-xl border border-border bg-background px-3 text-sm font-normal text-foreground"><option value="SET">Establecer stock final</option><option value="ADD">Sumar al stock actual</option></select></label>
          <label className="min-w-0 space-y-1.5 text-xs font-bold text-muted-foreground"><span className="flex flex-wrap items-center gap-1.5">Tasa manual de conversión <Badge variant={requiresManualExchangeRate ? 'destructive' : 'outline'} className="rounded-full px-1.5 py-0 text-[9px]">{requiresManualExchangeRate ? 'Requerida' : 'No necesaria'}</Badge></span><Input value={exchangeRate} onChange={(event) => { setExchangeRate(event.target.value); setPreview(null); }} inputMode="decimal" min="0" step="0.0001" type="number" required={requiresManualExchangeRate} disabled={!requiresManualExchangeRate} aria-invalid={requiresManualExchangeRate && !hasValidExchangeRate} placeholder={requiresManualExchangeRate ? 'Ej. 36.80' : 'Misma moneda'} /></label>
        </div>

        <div className="flex min-w-0 items-start gap-2 rounded-xl border border-amber-500/25 bg-amber-500/[0.06] px-3 py-2.5 text-xs text-muted-foreground"><AlertTriangle className="mt-0.5 size-4 shrink-0 text-amber-600" /><p className="min-w-0 leading-5">El Manager no tiene una tasa fija propia. {requiresManualExchangeRate ? <>Ingresa la tasa vigente para convertir <span className="font-bold text-foreground">{currency}</span> a <span className="font-bold text-foreground">{targetBaseCurrencyLabel}</span>; la importación no usará una tasa automática.</> : <>El archivo ya está expresado en la moneda base detectada ({targetBaseCurrencyLabel}) y no requiere conversión.</>}</p></div>
        {requiresManualExchangeRate && !hasValidExchangeRate && <div role="alert" className="rounded-xl border border-destructive/30 bg-destructive/5 px-3 py-2 text-xs text-destructive">Ingresa una tasa mayor que cero antes de previsualizar o confirmar la importación.</div>}

        <div className="grid min-w-0 grid-cols-1 gap-3 md:grid-cols-2 lg:grid-cols-3">
          <Card className="min-w-0 rounded-2xl border-primary/20 bg-primary/[0.04] shadow-none"><CardContent className="space-y-3 p-4"><div className="flex items-start gap-3"><div className="flex size-10 shrink-0 items-center justify-center rounded-xl bg-primary/10 text-primary"><FileSpreadsheet className="size-5" /></div><div className="min-w-0"><p className="font-black">1. Descarga la plantilla activa</p><p className="mt-1 text-xs leading-5 text-muted-foreground">Incluye dropdowns con sucursales y ubicaciones activas. Los almacenes corporativos aparecen fuera de sucursales; el sistema ya conoce sus sucursales autorizadas.</p></div></div><Button type="button" variant="outline" className="w-full rounded-xl" onClick={downloadTemplate} disabled={optionsQuery.isLoading || !options?.locations.length}><Download className="mr-2 size-4" />Descargar plantilla con ubicaciones</Button></CardContent></Card>
          <Card className="min-w-0 rounded-2xl border-primary/20 bg-primary/[0.04] shadow-none"><CardContent className="space-y-3 p-4"><div className="flex items-start gap-3"><div className="flex size-10 shrink-0 items-center justify-center rounded-xl bg-primary/10 text-primary"><Upload className="size-5" /></div><div className="min-w-0"><p className="font-black">2. Carga tu archivo</p><p className="mt-1 truncate text-xs leading-5 text-muted-foreground">{fileName || 'XLSX/XLS · Productos + Distribución'}</p></div></div><label className="flex h-10 cursor-pointer items-center justify-center rounded-xl border border-dashed border-primary/40 bg-background px-3 text-sm font-bold text-primary transition-colors hover:bg-primary/5"><input type="file" accept=".xlsx,.xls,.csv" onChange={onFile} className="sr-only" />{fileName ? 'Reemplazar archivo' : 'Seleccionar archivo'}</label></CardContent></Card>
          <Card className="min-w-0 rounded-2xl border-primary/20 bg-primary/[0.04] shadow-none"><CardContent className="space-y-3 p-4"><div className="flex items-start gap-3"><div className="flex size-10 shrink-0 items-center justify-center rounded-xl bg-primary/10 text-primary"><ImageIcon className="size-5" /></div><div className="min-w-0"><p className="font-black">3. Imágenes por SKU</p><p className="mt-1 truncate text-xs leading-5 text-muted-foreground">{imageArchiveFileName || 'Opcional · ZIP/RAR · JPG/PNG'}</p></div></div><label className="flex h-10 cursor-pointer items-center justify-center rounded-xl border border-dashed border-primary/40 bg-background px-3 text-sm font-bold text-primary transition-colors hover:bg-primary/5"><input type="file" accept=".zip,.rar,application/zip,application/vnd.rar,application/x-rar-compressed" onChange={onImageArchive} className="sr-only" disabled={imageArchiveProcessing} />{imageArchiveProcessing ? 'Leyendo imágenes…' : imageArchiveFileName ? 'Reemplazar ZIP/RAR' : 'Seleccionar ZIP/RAR'}</label></CardContent></Card>
        </div>

        <div className="flex min-w-0 items-start gap-3 rounded-2xl border border-sky-500/20 bg-sky-500/[0.06] p-4 text-sm"><Info className="mt-0.5 size-4 shrink-0 text-sky-600" /><p className="min-w-0 leading-5 text-muted-foreground">Rubro seleccionado: <span className="font-bold text-foreground">{selectedBusinessUnitName}</span>. La hoja <span className="font-bold text-foreground">Productos</span> define cada SKU una sola vez y <span className="font-bold text-foreground">Distribución</span> indica cuánto va a cada ubicación. Una <span className="font-bold text-foreground">BODEGA</span> pertenece a su sucursal; un <span className="font-bold text-foreground">ALMACÉN</span> está fuera de las sucursales. Para BODEGA se elige la sucursal; para ALMACÉN se deja vacía porque el backend usa las sucursales autorizadas en su configuración. Se usan nombres visibles, no IDs. El costo es obligatorio y único por SKU. El backend solo aceptará ubicaciones activas y autorizadas del rubro. Stock <span className="font-bold text-foreground">0</span> crea el registro sin generar movimiento. Las imágenes opcionales se asocian por SKU desde ZIP o RAR.</p></div>

        {optionsQuery.isLoading && <div className="flex items-center justify-center gap-2 py-8 text-sm text-muted-foreground"><Loader2 className="size-4 animate-spin" />Cargando ubicaciones activas…</div>}
        {optionsQuery.isError && <div className="rounded-2xl border border-destructive/30 bg-destructive/5 p-4 text-sm text-destructive">No se pudieron cargar las ubicaciones activas. {optionsQuery.error.message}</div>}
        {options?.branches.length === 0 && <div className="rounded-2xl border border-amber-500/30 bg-amber-500/10 p-4 text-sm text-amber-700 dark:text-amber-300">No hay sucursales activas para este rubro. La importación queda bloqueada.</div>}
        {options && options.branches.length > 0 && <div className="grid min-w-0 grid-cols-1 gap-2 sm:grid-cols-2 lg:grid-cols-3">{options.branches.map((branch) => <div key={branch.id} className="flex min-w-0 items-center justify-between gap-3 rounded-xl border border-border/60 bg-muted/20 px-3 py-2.5"><span className="min-w-0 truncate text-sm font-semibold">{branch.name}</span><Badge variant="outline" className="shrink-0 rounded-full text-[10px]">{locationsByBranch.get(branch.id) || 0} relaciones</Badge></div>)}</div>}

        {rows.length > 0 && <div className="space-y-3 rounded-2xl border border-border/60 p-3 sm:p-4"><div className="flex flex-wrap items-center justify-between gap-2"><div><p className="text-xs font-black uppercase tracking-widest text-muted-foreground">Archivo listo para validar</p><p className="mt-1 text-sm font-semibold">{sheetSummary?.format === 'two-sheet' ? `${sheetSummary.productRows} producto(s) · ${sheetSummary.distributionRows} distribución(es)` : `${rows.length} fila(s)`} · {fileName}</p></div><Button type="button" className="rounded-xl" onClick={() => previewMutation.mutate()} disabled={!importBusinessUnitId || !hasValidExchangeRate || previewMutation.isPending || optionsQuery.isLoading || imageArchiveProcessing}><PackagePlus className="mr-2 size-4" />{previewMutation.isPending ? 'Previsualizando…' : 'Previsualizar importación'}</Button></div><div className="overflow-x-auto rounded-xl border border-border/60"><table className="min-w-[940px] w-full text-left text-xs"><thead className="bg-muted/40 text-[10px] font-black uppercase tracking-widest text-muted-foreground"><tr><th className="px-3 py-2">Fila</th><th className="px-3 py-2">Código / SKU</th><th className="px-3 py-2">Nombre</th><th className="px-3 py-2">Sucursal / relación</th><th className="px-3 py-2">Ubicación</th><th className="px-3 py-2">Imagen</th><th className="px-3 py-2">Stock inicial</th></tr></thead><tbody>{rows.slice(0, 8).map((row, index) => { const code = rowCode(row); return <tr key={index} className="border-t border-border/50"><td className="px-3 py-2 text-muted-foreground">{index + 2}</td><td className="px-3 py-2 font-mono font-bold">{code || '—'}</td><td className="max-w-48 truncate px-3 py-2">{String(row.Nombre ?? row.name ?? row.nombre ?? '—')}</td><td className="max-w-48 truncate px-3 py-2">{String(row['Sucursal vinculada / catálogo'] ?? row['Sucursal destino'] ?? row.sucursal ?? row.branchName ?? '—') || '—'}</td><td className="max-w-48 truncate px-3 py-2">{String(row['Ubicación destino'] ?? row.Bodega ?? row.bodega ?? row.Ubicación ?? row.ubicacion ?? row.warehouse ?? '—')}</td><td className="px-3 py-2">{imageArchiveFileName ? (imageArchiveEntries.has(code.toLowerCase()) ? 'Vinculada' : 'No encontrada') : '—'}</td><td className="px-3 py-2 font-bold">{String(row['Stock inicial'] ?? row.Stock ?? row.stock ?? row.Cantidad ?? row.cantidad ?? '0')}</td></tr>; })}</tbody></table>{rows.length > 8 && <p className="px-3 py-2 text-xs text-muted-foreground">Mostrando 8 de {rows.length} filas. La validación se ejecutará sobre todas.</p>}</div></div>}

        {preview && <PreviewPanel preview={preview} />}
      </div>}
      </div>
      <div className="flex flex-col gap-3 border-t border-border/60 bg-muted/10 px-4 py-5 sm:flex-row sm:items-center sm:justify-between sm:px-8"><p className="text-left text-xs leading-5 text-muted-foreground sm:max-w-xl">Se conserva el precio al costo del archivo, convertido a la moneda base de cada sucursal cuando corresponda. La operación confirmada es atómica.</p><div className="flex w-full gap-2 sm:w-auto"><Button type="button" variant="outline" className="flex-1 rounded-xl sm:flex-none" onClick={onBack}>Volver</Button><Button type="button" className="flex-1 rounded-xl sm:flex-none" disabled={!validForImport || !hasValidExchangeRate || importMutation.isPending} onClick={() => importMutation.mutate()}>{importMutation.isPending ? <><Loader2 className="mr-2 size-4 animate-spin" />Aplicando…</> : <><CheckCircle2 className="mr-2 size-4" />Confirmar importación</>}</Button></div></div>
    </div>
  </section>;
}

function PreviewPanel({ preview }: { preview: ManagerInventoryImportPreview }) {
  const hasErrors = preview.errors.length > 0;
  return <div className="space-y-3 rounded-2xl border border-border/60 p-3 sm:p-4"><div className="flex flex-wrap items-center justify-between gap-2"><div><p className="text-xs font-black uppercase tracking-widest text-muted-foreground">3. Previsualización y normalización</p><p className="mt-1 text-sm text-muted-foreground">{hasErrors ? 'Corrige los errores del archivo antes de confirmar.' : 'Todas las filas son válidas y apuntan a ubicaciones activas.'}</p></div><Badge variant={hasErrors ? 'destructive' : 'default'} className="rounded-full">{hasErrors ? `${preview.summary.errorRows} con error` : 'Lista para confirmar'}</Badge></div><div className="grid min-w-0 grid-cols-2 gap-2 md:grid-cols-4 xl:grid-cols-7"><Summary label="Filas" value={preview.summary.totalRows} /><Summary label="Válidas" value={preview.summary.validRows} /><Summary label="Productos" value={preview.summary.products} /><Summary label="Ubicaciones" value={preview.summary.locations} /><Summary label="Unidades" value={preview.summary.importedUnits} /><Summary label="Resultado" value={preview.summary.resultingUnits} /><Summary label={`Valor ${preview.currency}`} value={preview.summary.value} /></div>{hasErrors && <div className="max-h-32 overflow-y-auto rounded-xl border border-destructive/20 bg-destructive/5 p-3 text-xs text-destructive">{preview.errors.slice(0, 50).map((error, index) => <p key={`${error}-${index}`} className="flex gap-2 py-0.5"><AlertTriangle className="mt-0.5 size-3 shrink-0" />{error}</p>)}{preview.errors.length > 50 && <p className="pt-1 font-bold">Se muestran los primeros 50 errores.</p>}</div>}<div className="overflow-x-auto rounded-xl border border-border/60"><table className="min-w-[1060px] w-full text-left text-xs"><thead className="bg-muted/40 text-[10px] font-black uppercase tracking-widest text-muted-foreground"><tr><th className="px-3 py-2">Fila</th><th className="px-3 py-2">Producto</th><th className="px-3 py-2">Sucursal / ubicación</th><th className="px-3 py-2">Estado</th><th className="px-3 py-2">Ubicación</th><th className="px-3 py-2">Actual</th><th className="px-3 py-2">Resultado</th><th className="px-3 py-2">Observación</th></tr></thead><tbody>{preview.rows.slice(0, 100).map((row) => <tr key={`${row.rowNumber}-${row.code}-${row.warehouseId}`} className="border-t border-border/50 align-top"><td className="px-3 py-2 text-muted-foreground">{row.rowNumber}</td><td className="px-3 py-2"><p className="font-mono font-bold">{row.code}</p><p className="max-w-48 truncate text-muted-foreground">{row.productName}</p></td><td className="px-3 py-2"><p>{preview.locations.find((location) => location.branchId === row.branchId)?.branchName || '—'}</p><p className="text-muted-foreground">{row.warehouseName || '—'}</p></td><td className="px-3 py-2"><Badge variant={row.issues.length ? 'destructive' : 'outline'} className="whitespace-nowrap">{row.issues.length ? 'Error' : statusLabels[row.status] || row.status}</Badge></td><td className="px-3 py-2"><span className="flex items-center gap-1.5"><Warehouse className="size-3.5 text-primary" />{row.locationStatus.replaceAll('_', ' ')}</span></td><td className="px-3 py-2 font-bold">{formatNumber(row.currentQty)}</td><td className="px-3 py-2 font-black text-primary">{formatNumber(row.resultingQty)}</td><td className="max-w-64 px-3 py-2 text-destructive">{row.issues.join(' · ') || 'Sin observaciones'}</td></tr>)}</tbody></table>{preview.rows.length > 100 && <p className="px-3 py-2 text-xs text-muted-foreground">Mostrando 100 de {preview.rows.length} filas.</p>}</div></div>;
}

function Summary({ label, value }: { label: string; value: unknown }) {
  return <div className="min-w-0 rounded-xl bg-muted/30 p-2.5"><p className="truncate text-[9px] font-black uppercase tracking-wider text-muted-foreground">{label}</p><p className="mt-1 truncate text-sm font-black tabular-nums">{formatNumber(value)}</p></div>;
}
